(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("arist-plutus-e",[{"st": "—", "sp": "HDR", "t": "ΠΛΟΥΤΟΣ"}, {"st": null, "sp": "Καρίων", "t": "ὡς ἀργαλέον πρᾶγμ᾽ ἐστὶν ὦ Ζεῦ καὶ θεοὶ<br>δοῦλον γενέσθαι παραφρονοῦντος δεσπότου.<br>ἢν γὰρ τὰ βέλτισθ᾽ ὁ θεράπων λέξας τύχῃ,<br>δόξῃ δὲ μὴ δρᾶν ταῦτα τῷ κεκτημένῳ,<br>μετέχειν ἀνάγκη τὸν θεράποντα τῶν κακῶν.<br>τοῦ σώματος γὰρ οὐκ ἐᾷ τὸν κύριον<br>κρατεῖν ὁ δαίμων, ἀλλὰ τὸν ἐωνημένον.<br>καὶ ταῦτα μὲν δὴ ταῦτα. τῷ δὲ Λοξίᾳ,<br>ὃς θεσπιῳδεῖ τρίποδος ἐκ χρυσηλάτου,<br>μέμψιν δικαίαν μέμφομαι ταύτην, ὅτι<br>ἰατρὸς ὢν καὶ μάντις, ὥς φασιν, σοφὸς<br>μελαγχολῶντ᾽ ἀπέπεμψέ μου τὸν δεσπότην,<br>ὅστις ἀκολουθεῖ κατόπιν ἀνθρώπου τυφλοῦ,<br>τοὐναντίον δρῶν ἢ προσῆκ᾽ αὐτῷ ποιεῖν.<br>οἱ γὰρ βλέποντες τοῖς τυφλοῖς ἡγούμεθα,<br>οὗτος δ᾽ ἀκολουθεῖ, κἀμὲ προσβιάζεται,<br>καὶ ταῦτ᾽ ἀποκρινομένῳ τὸ παράπαν οὐδὲ γρῦ.<br>ἐγὼ μὲν οὖν οὐκ ἔσθ᾽ ὅπως σιγήσομαι,<br>ἢν μὴ φράσῃς ὅ τι τῷδ᾽ ἀκολουθοῦμέν ποτε<br>ὦ δέσποτ᾽, ἀλλά σοι παρέξω πράγματα.<br>οὐ γάρ με τυπτήσεις στέφανον ἔχοντά γε."}, {"st": null, "sp": "Χρεμύλος", "t": "μὰ Δί᾽ ἀλλ᾽ ἀφελὼν τὸν στέφανον, ἢν λυπῇς τί με,<br>ἵνα μᾶλλον ἀλγῇς."}, {"st": null, "sp": "Καρίων", "t": "λῆρος: οὐ γὰρ παύσομαι<br>πρὶν ἂν φράσῃς μοι τίς ποτ᾽ ἐστὶν οὑτοσί:<br>εὔνους γὰρ ὤν σοι πυνθάνομαι πάνυ σφόδρα."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλ᾽ οὔ σε κρύψω: τῶν ἐμῶν γὰρ οἰκετῶν<br>πιστότατον ἡγοῦμαί σε καὶ κλεπτίστατον.<br>ἐγὼ θεοσεβὴς καὶ δίκαιος ὢν ἀνὴρ<br>κακῶς ἔπραττον καὶ πένης ἦν:"}, {"st": null, "sp": "Καρίων", "t": "οἶδά τοι."}, {"st": "30", "sp": "Χρεμύλος", "t": "ἕτεροι δ᾽ ἐπλούτουν ἱερόσυλοι ῥήτορες<br>καὶ συκοφάνται καὶ πονηροί:"}, {"st": null, "sp": "Καρίων", "t": "πείθομαι."}, {"st": null, "sp": "Χρεμύλος", "t": "ἐπερησόμενος οὖν ᾠχόμην ὡς τὸν θεόν,<br>τὸν ἐμὸν μὲν αὐτοῦ τοῦ ταλαιπώρου σχεδὸν<br>ἤδη νομίζων ἐκτετοξεῦσθαι βίον,<br>τὸν δ᾽ υἱόν, ὅσπερ ὢν μόνος μοι τυγχάνει,<br>πευσόμενος εἰ χρὴ μεταβαλόντα τοὺς τρόπους<br>εἶναι πανοῦργον, ἄδικον, ὑγιὲς μηδὲ ἕν,<br>ὡς τῷ βίῳ τοῦτ᾽ αὐτὸ νομίσας συμφέρειν."}, {"st": null, "sp": "Καρίων", "t": "τί δῆτα Φοῖβος ἔλακεν ἐκ τῶν στεμμάτων;"}, {"st": "40", "sp": "Χρεμύλος", "t": "πεύσει. σαφῶς γὰρ ὁ θεὸς εἶπέ μοι τοδί:<br>ὅτῳ ξυναντήσαιμι πρῶτον ἐξιών,<br>ἐκέλευε τούτου μὴ μεθίεσθαί μ᾽ ἔτι,<br>πείθειν δ᾽ ἐμαυτῷ ξυνακολουθεῖν οἴκαδε."}, {"st": null, "sp": "Καρίων", "t": "καὶ τῷ ξυναντᾷς δῆτα πρώτῳ;"}, {"st": null, "sp": "Χρεμύλος", "t": "τουτῳί."}, {"st": "45", "sp": "Καρίων", "t": "εἶτ᾽ οὐ ξυνίης τὴν ἐπίνοιαν τοῦ θεοῦ<br>φράζουσαν ὦ σκαιότατέ σοι σαφέστατα<br>ἀσκεῖν τὸν υἱὸν τὸν ἐπιχώριον τρόπον;"}, {"st": null, "sp": "Χρεμύλος", "t": "τῷ τοῦτο κρίνεις;"}, {"st": null, "sp": "Καρίων", "t": "δῆλον ὁτιὴ καὶ τυφλῷ<br>γνῶναι δοκεῖ τοῦθ᾽, ὡς σφόδρ᾽ ἐστὶ συμφέρον<br>τὸ μηδὲν ἀσκεῖν ὑγιὲς ἐν τῷ νῦν χρόνῳ."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐκ ἔσθ᾽ ὅπως ὁ χρησμὸς ἐς τοῦτο ῥέπει,<br>ἀλλ᾽ εἰς ἕτερόν τι μεῖζον. ἢν δ᾽ ἡμῖν φράσῃ<br>ὅστις ποτ᾽ ἐστὶν οὑτοσὶ καὶ τοῦ χάριν<br>καὶ τοῦ δεόμενος ἦλθε μετὰ νῷν ἐνθαδί,<br>πυθοιμεθ᾽ ἂν τὸν χρησμὸν ἡμῶν ὅ τι νοεῖ."}, {"st": null, "sp": "Καρίων", "t": "ἄγε δὴ σὺ πότερον σαυτὸν ὅστις εἶ φράσεις,<br>ἢ τἀπὶ τούτοις δρῶ; λέγειν χρὴ ταχὺ πάνυ."}, {"st": null, "sp": "Πλοῦτος", "t": "ἐγὼ μὲν οἰμώζειν λέγω σοι."}, {"st": null, "sp": "Καρίων", "t": "μαναθάνεις<br>ὅς φησιν εἶναι;"}, {"st": null, "sp": "Χρεμύλος", "t": "σοὶ λέγει τοῦτ᾽, οὐκ ἐμοί:<br>σκαιῶς γὰρ αὐτοῦ καὶ χαλεπῶς ἐκπυνθάνει.<br>ἀλλ᾽ εἴ τι χαίρεις ἀνδρὸς εὐόρκου τρόποις,<br>ἐμοὶ φράσον."}, {"st": null, "sp": "Πλοῦτος", "t": "κλάειν ἔγωγέ σοι λέγω."}, {"st": null, "sp": "Καρίων", "t": "δέχου τὸν ἄνδρα καὶ τὸν ὄρνιν τοῦ θεοῦ."}, {"st": null, "sp": "Χρεμύλος", "t": "οὔ τοι μὰ τὴν Δήμητρα χαιρήσεις ἔτι.<br>εἰ μὴ φράσεις γάρ —"}, {"st": null, "sp": "Καρίων", "t": "ἀπό σ᾽ ὀλῶ κακὸν κακῶς."}, {"st": null, "sp": "Χρεμύλος", "t": "ὦ τᾶν —"}, {"st": null, "sp": "Πλοῦτος", "t": "ἀπαλλάχθητον ἀπ᾽ ἐμοῦ."}, {"st": null, "sp": "Χρεμύλος", "t": "πώμαλα."}, {"st": null, "sp": "Καρίων", "t": "καὶ μὴν ὃ λέγω βέλτιστόν ἐστ᾽ ὦ δέσποτα.<br>ἀπολῶ τὸν ἄνθρωπον κάκιστα τουτονί.<br>ἀναθεὶς γὰρ ἐπὶ κρημνόν τιν᾽ αὐτὸν καταλιπων<br>ἄπειμ᾽, ἵν᾽ ἐκεῖθεν ἐκτραχηλισθῇ πεσών."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλ᾽ αἶρε ταχέως."}, {"st": null, "sp": "Πλοῦτος", "t": "μηδαμῶς."}, {"st": null, "sp": "Χρεμύλος", "t": "οὔκουν ἐρεῖς;"}, {"st": null, "sp": "Πλοῦτος", "t": "ἀλλ᾽ ἢν πύθησθέ μ᾽ ὅστις εἴμ᾽, εὖ οἶδ᾽ ὅτι<br>κακόν τί μ᾽ ἐργάσεσθε κοὐκ ἀφήσετον."}, {"st": null, "sp": "Χρεμύλος", "t": "νὴ τοὺς θεοὺς ἡμεῖς γ᾽, ἐὰν βούλῃ γε σύ."}, {"st": "75", "sp": "Πλοῦτος", "t": "μέθεσθε νῦν μου πρῶτον."}, {"st": null, "sp": "Χρεμύλος", "t": "ἤν, μεθίεμεν."}, {"st": null, "sp": "Πλοῦτος", "t": "ἀκούετον δή: δεῖ γὰρ ὡς ἔοικέ με<br>λέγειν ἃ κρύπτειν ἦν παρεσκευασμένος.<br>ἐγὼ γάρ εἰμι Πλοῦτος."}, {"st": null, "sp": "Χρεμύλος", "t": "ὦ μιαρώτατε<br>ἀνδρῶν ἁπάντων, εἶτ᾽ ἐσίγας Πλοῦτος ὤν;"}, {"st": "80", "sp": "Καρίων", "t": "σὺ Πλοῦτος, οὕτως ἀθλίως διακείμενος;<br>ὦ Φοῖβ᾽ Ἄπολλον καὶ θεοὶ καὶ δαίμονες<br>καὶ Ζεῦ, τί φῄς; ἐκεῖνος ὄντως εἶ σύ;"}, {"st": null, "sp": "Πλοῦτος", "t": "ναί."}, {"st": null, "sp": "Χρεμύλος", "t": "ἐκεῖνος αὐτός;"}, {"st": null, "sp": "Πλοῦτος", "t": "αὐτότατος."}, {"st": null, "sp": "Χρεμύλος", "t": "πόθεν οὖν φράσον<br>αὐχμῶν βαδίζεις;"}, {"st": null, "sp": "Πλοῦτος", "t": "ἐκ Πατροκλέους ἔρχομαι,<br>ὃς οὐκ ἐλούσατ᾽ ἐξ ὅτουπερ ἐγένετο."}, {"st": null, "sp": "Χρεμύλος", "t": "τουτὶ δὲ τὸ κακὸν πῶς ἔπαθες; κάτειπέ μοι."}, {"st": null, "sp": "Πλοῦτος", "t": "ὁ Ζεύς με ταῦτ᾽ ἔδρασεν ἀνθρώποις φθονῶν.<br>ἐγὼ γὰρ ὢν μειράκιον ἠπείλησ᾽ ὅτι<br>ὡς τοὺς δικαίους καὶ σοφοὺς καὶ κοσμίους<br>μόνους βαδιοίμην: ὁ δέ μ᾽ ἐποίησεν τυφλόν,<br>ἵνα μὴ διαγιγνώσκοιμι τούτων μηδένα.<br>οὕτως ἐκεῖνος τοῖσι χρηστοῖσι φθονεῖ."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ μὴν διὰ τοὺς χρηστούς γε τιμᾶται μόνους<br>καὶ τοὺς δικαίους."}, {"st": null, "sp": "Πλοῦτος", "t": "ὁμολογῶ σοι."}, {"st": null, "sp": "Χρεμύλος", "t": "φέρε τί οὖν;<br>εἰ πάλιν ἀναβλέψειας ὥσπερ καὶ πρὸ τοῦ,<br>φεύγοις ἂν ἤδη τοὺς πονηρούς;"}, {"st": null, "sp": "Πλοῦτος", "t": "φήμ᾽ ἐγώ."}, {"st": null, "sp": "Χρεμύλος", "t": "ὡς τοὺς δικαίους δ᾽ ἂν βαδίζοις;"}, {"st": null, "sp": "Πλοῦτος", "t": "πάνυ μὲν οὖν:<br>πολλοῦ γὰρ αὐτοὺς οὐχ ἑόρακά πω χρόνου."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ θαῦμά γ᾽ οὐδέν: οὐδ᾽ ἐγὼ γὰρ ὁ βλέπων."}, {"st": "100", "sp": "Πλοῦτος", "t": "ἄφετόν με νῦν. ἴστον γὰρ ἤδη τἀπ᾽ ἐμοῦ."}, {"st": null, "sp": "Χρεμύλος", "t": "μὰ Δί᾽ ἀλλὰ πολλῷ μᾶλλον ἑξόμεσθά σου."}, {"st": null, "sp": "Πλοῦτος", "t": "οὐκ ἠγόρευον ὅτι παρέξειν πράγματα<br>ἐμέλλετόν μοι;"}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ σύ γ᾽ ἀντιβολῶ πιθοῦ,<br>καὶ μή μ᾽ ἀπολίπῃς: οὐ γὰρ εὑρήσεις ἐμοῦ<br>ζητῶν ἔτ᾽ ἄνδρα τοὺς τρόπους βελτίονα."}, {"st": null, "sp": "Καρίων", "t": "μὰ τὸν Δί᾽ οὐ γὰρ ἔστιν ἄλλος πλὴν ἐγώ."}, {"st": null, "sp": "Πλοῦτος", "t": "ταυτὶ λέγουσι πάντες: ἡνίκ᾽ ἂν δέ μου<br>τύχωσ᾽ ἀληθῶς καὶ γένωνται πλούσιοι,<br>ἀτεχνῶς ὑπερβάλλουσι τῇ μοχθηρίᾳ."}, {"st": "110", "sp": "Χρεμύλος", "t": "ἔχει μὲν οὕτως, εἰσὶ δ᾽ οὐ πάντες κακοί."}, {"st": null, "sp": "Πλοῦτος", "t": "μὰ Δί᾽ ἀλλ᾽ ἁπαξάπαντες."}, {"st": null, "sp": "Καρίων", "t": "οἰμώξει μακρά."}, {"st": null, "sp": "Χρεμύλος", "t": "σοὶ δ᾽ ὡς ἂν εἰδῇς ὅσα παρ᾽ ἡμῖν ἢν μένῃς<br>γενήσετ᾽ ἀγαθά, πρόσεχε τὸν νοῦν ἵνα πύθῃ.<br>οἶμαι γὰρ οἶμαι, σὺν θεῷ δ᾽ εἰρήσεται,<br>ταύτης ἀπαλλάξειν σε τῆς ὀφθαλμίας<br>βλέψαι ποιήσας."}, {"st": null, "sp": "Πλοῦτος", "t": "μηδαμῶς τοῦτ᾽ ἐργάσῃ.<br>οὐ βούλομαι γὰρ πάλιν ἀναβλέψαι."}, {"st": null, "sp": "Χρεμύλος", "t": "τί φῄς;"}, {"st": null, "sp": "Καρίων", "t": "ἅνθρωπος οὗτός ἐστιν ἄθλιος φύσει."}, {"st": null, "sp": "Πλοῦτος", "t": "ὁ Ζεὺς † μὲν οὖν εἰδὼς τὰ τούτων μῶρ᾽ ἔμ᾽ εἰ†<br>πύθοιτ᾽ ἂν ἐπιτρίψειε."}, {"st": null, "sp": "Χρεμύλος", "t": "νῦν δ᾽ οὐ τοῦτο δρᾷ,<br>ὅστις σε προσπταίοντα περινοστεῖν ἐᾷ;"}, {"st": null, "sp": "Πλοῦτος", "t": "οὐκ οἶδ᾽: ἐγὼ δ᾽ ἐκεῖνον ὀρρωδῶ πάνυ."}, {"st": null, "sp": "Χρεμύλος", "t": "ἄληθες ὦ δειλότατε πάντων δαιμόνων;<br>οἴει γὰρ εἶναι τὴν Διὸς τυραννίδα<br>καὶ τοὺς κεραυνοὺς ἀξίους τριωβόλου,<br>ἐὰν ἀναβλέψῃς σὺ κἂν σμικρὸν χρόνον;"}, {"st": null, "sp": "Πλοῦτος", "t": "ἆ μὴ λέγ᾽ ὦ πόνηρε ταῦτ᾽."}, {"st": null, "sp": "Χρεμύλος", "t": "ἔχ᾽ ἥσυχος.<br>ἐγὼ γὰρ ἀποδείξω σε τοῦ Διὸς πολὺ<br>μεῖζον δυνάμενον."}, {"st": null, "sp": "Πλοῦτος", "t": "ἐμὲ σύ;"}, {"st": null, "sp": "Χρεμύλος", "t": "νὴ τὸν οὐρανόν.<br>αὐτίκα γὰρ ἄρχει διὰ τίν᾽ ὁ Ζεὺς τῶν θεῶν;"}, {"st": null, "sp": "Καρίων", "t": "διὰ τἀργύριον: πλεῖστον γάρ ἐστ᾽ αὐτῷ."}, {"st": null, "sp": "Χρεμύλος", "t": "φέρε<br>τίς οὖν ὁ παρέχων ἐστὶν αὐτῷ τοῦθ᾽;"}, {"st": null, "sp": "Καρίων", "t": "ὁδί."}, {"st": null, "sp": "Χρεμύλος", "t": "θύουσι δ᾽ αὐτῷ διὰ τίν᾽; οὐ διὰ τουτονί;"}, {"st": null, "sp": "Καρίων", "t": "καὶ νὴ Δί᾽ εὔχονταί γε πλουτεῖν ἄντικρυς."}, {"st": "135", "sp": "Χρεμύλος", "t": "οὔκουν ὅδ᾽ ἐστὶν αἴτιος καὶ ῥᾳδίως<br>παύσειεν, εἰ βούλοιτο, ταῦτ᾽ ἄν;"}, {"st": null, "sp": "Πλοῦτος", "t": "ὅτι τί δή;"}, {"st": null, "sp": "Χρεμύλος", "t": "ὅτι οὐδ᾽ ἂν εἷς θύσειεν ἀνθρώπων ἔτι,<br>οὐ βοῦν ἄν, οὐχὶ ψαιστόν, οὐκ ἄλλ᾽ οὐδὲ ἕν,<br>μὴ βουλομένου σοῦ."}, {"st": null, "sp": "Πλοῦτος", "t": "πῶς;"}, {"st": null, "sp": "Χρεμύλος", "t": "ὅπως;<br>οὐκ ἔσθ᾽ ὅπως<br>ὠνήσεται δήπουθεν, ἢν σὺ μὴ παρὼν<br>αὐτὸς διδῷς τἀργύριον: ὥστε τοῦ Διὸς<br>τὴν δύνομιν, ἢν λυπῇ τι, καταλύσεις μόνος."}, {"st": null, "sp": "Πλοῦτος", "t": "τί λέγεις; δι᾽ ἐμὲ θύουσιν αὐτῷ;"}, {"st": null, "sp": "Χρεμύλος", "t": "φήμ᾽ ἐγώ.<br>καὶ νὴ Δί᾽ εἴ τί γ᾽ ἔστι λαμπρὸν καὶ καλὸν<br>ἢ χαρίεν ἀνθρώποισι, διὰ σὲ γίγνεται.<br>ἅπαντα τῷ πλουτεῖν γάρ ἐσθ᾽ ὑπήκοα."}, {"st": null, "sp": "Καρίων", "t": "ἔγωγέ τοι διὰ μικρὸν ἀργυρίδιον<br>δοῦλος γεγένημαι, διὰ τὸ μὴ πλουτεῖν ἴσως."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ τάς γ᾽ ἑταίρας φασὶ τὰς Κορινθίας,<br>ὅταν μὲν αὐτάς τις πένης πειρῶν τύχῃ,<br>οὐδὲ προσέχειν τὸν νοῦν, ἐὰν δὲ πλούσιος,<br>τὸν πρωκτὸν αὐτὰς εὐθὺς ὡς τοῦτον τρέπειν."}, {"st": null, "sp": "Καρίων", "t": "καὶ τούς γε παῖδάς φασι ταὐτὸ τοῦτο δρᾶν<br>οὐ τῶν ἐραστῶν ἀλλὰ τἀργυρίου χάριν."}, {"st": "155", "sp": "Χρεμύλος", "t": "οὐ τούς γε χρηστούς, ἀλλὰ τοὺς πόρνους: ἐπεὶ<br>αἰτοῦσιν οὐκ ἀργύριον οἱ χρηστοί."}, {"st": null, "sp": "Καρίων", "t": "τί δαί;"}, {"st": null, "sp": "Χρεμύλος", "t": "ὁ μὲν ἵππον ἀγαθόν, ὁ δὲ κύνας θηρευτικάς."}, {"st": null, "sp": "Καρίων", "t": "αἰσχυνόμενοι γὰρ ἀργύριον αἰτεῖν ἴσως<br>ὀνόματι περιπέττουσι τὴν μοχθηρίαν."}, {"st": "160", "sp": "Χρεμύλος", "t": "τέχναι δὲ πᾶσαι διὰ σὲ καὶ σοφίσματα<br>ἐν τοῖσιν ἀνθρώποισίν ἐσθ᾽ ηὑρημένα.<br>ὁ μὲν γὰρ ἡμῶν σκυτοτομεῖ καθήμενος:"}, {"st": null, "sp": "Καρίων", "t": "ἕτερος δὲ χαλκεύει τις, ὁ δὲ τεκταίνεται:"}, {"st": null, "sp": "Χρεμύλος", "t": "ὁ δὲ χρυσοχοεῖ γε χρυσίον παρὰ σοῦ λαβών:"}, {"st": "165", "sp": "Καρίων", "t": "ὁ δὲ λωποδυτεῖ γε νὴ Δί᾽, ὁ δὲ τοιχωρυχεῖ:"}, {"st": null, "sp": "Χρεμύλος", "t": "ὁ δὲ γναφεύει γ᾽:"}, {"st": null, "sp": "Καρίων", "t": "ὁ δέ γε πλύνει κῴδια:"}, {"st": null, "sp": "Χρεμύλος", "t": "ὁ δὲ βυρσοδεψεῖ γ᾽:"}, {"st": null, "sp": "Καρίων", "t": "ὁ δέ γε πωλεῖ κρόμμυα:"}, {"st": null, "sp": "Χρεμύλος", "t": "ὁ δ᾽ ἁλούς γε μοιχὸς διὰ σέ που παρατίλλεται."}, {"st": null, "sp": "Πλοῦτος", "t": "οἴμοι τάλας ταυτί μ᾽ ἐλάνθανεν πάλαι."}, {"st": "170", "sp": "Καρίων", "t": "μέγας δὲ βασιλεὺς οὐχὶ διὰ τοῦτον κομᾷ;"}, {"st": null, "sp": "Χρεμύλος", "t": "ἐκκλησία δ᾽ οὐχὶ διὰ τοῦτον γίγνεται;"}, {"st": null, "sp": "Καρίων", "t": "τί δέ; τὰς τριήρεις οὐ σὺ πληροῖς; εἰπέ μοι."}, {"st": null, "sp": "Χρεμύλος", "t": "τὸ δ᾽ ἐν Κορίνθῳ ξενικὸν οὐχ οὗτος τρέφει;"}, {"st": null, "sp": "Καρίων", "t": "ὁ Πάμφιλος δ᾽ οὐχι διὰ τοῦτον κλαύσεται;"}, {"st": "175", "sp": "Χρεμύλος", "t": "ὁ βελονοπώλης δ᾽ οὐχὶ μετὰ τοῦ Παμφίλου;"}, {"st": null, "sp": "Καρίων", "t": "Ἀγύρριος δ᾽ οὐχὶ διὰ τοῦτον πέρδεται;"}, {"st": null, "sp": "Χρεμύλος", "t": "Φιλέψιος δ᾽ οὐχ ἕνεκα σοῦ μύθους λέγει;"}, {"st": null, "sp": "Καρίων", "t": "ἡ ξυμμαχία δ᾽ οὐ διὰ σὲ τοῖς Αἰγυπτίοις;"}, {"st": null, "sp": "Χρεμύλος", "t": "ἐρᾷ δὲ Λαῒς οὐ διὰ σὲ Φιλωνίδου;"}, {"st": "180", "sp": "Καρίων", "t": "ὁ Τιμοθέου δὲ πύργος —"}, {"st": null, "sp": "Χρεμύλος", "t": "ἐμπέσοι γέ σοι.<br>τὰ δὲ πράγματ᾽ οὐχὶ διὰ σὲ πάντα πράττεται;<br>μονώτατος γὰρ εἶ σὺ πάντων αἴτιος<br>καὶ τῶν κακῶν καὶ τῶν ἀγαθῶν, εὖ ἴσθ᾽ ὅτι."}, {"st": null, "sp": "Καρίων", "t": "κρατοῦσι γοῦν κἀν τοῖς πολέμοις ἑκάστοτε,<br>ἐφ᾽ οἷς οὗτος ἐπικαθέζηται μόνον."}, {"st": null, "sp": "Πλοῦτος", "t": "ἐγὼ τοσαῦτα δυνατός εἰμ᾽ εἷς ὢν ποιεῖν;"}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ ναὶ μὰ Δία τούτων γε πολλῷ πλείονα:<br>ὥστ᾽ οὐδὲ μεστὸς σοῦ γέγον᾽ οὐδεὶς πώποτε.<br>τῶν μὲν γὰρ ἄλλων ἐστὶ πάντων πλησμονή,<br>ἔρωτος"}, {"st": null, "sp": "Καρίων", "t": "ἄρτων"}, {"st": null, "sp": "Χρεμύλος", "t": "μουσικῆς"}, {"st": null, "sp": "Καρίων", "t": "τραγημάτων"}, {"st": null, "sp": "Καρίων", "t": "πλακούντων"}, {"st": null, "sp": "Χρεμύλος", "t": "ἀνδραγαθίας"}, {"st": null, "sp": "Καρίων", "t": "ἰσχάδων"}, {"st": null, "sp": "Καρίων", "t": "μάζης"}, {"st": null, "sp": "Χρεμύλος", "t": "στρατηγίας"}, {"st": null, "sp": "Καρίων", "t": "φακῆς:"}, {"st": null, "sp": "Χρεμύλος", "t": "σοῦ δ᾽ ἐγένετ᾽ οὐδεὶς μεστὸς οὐδεπώποτε.<br>ἀλλ᾽ ἢν τάλαντά τις λάβῃ τριακαίδεκα,<br>πολὺ μᾶλλον ἐπιθυμεῖ λαβεῖν ἑκκαίδεκα:<br>κἂν ταῦτ᾽ ἀνύσηται, τετταράκοντα βούλεται,<br>ἤ φησιν εἶν ἀβίωτον αὑτῷ τὸν βίον."}, {"st": null, "sp": "Πλοῦτος", "t": "εὖ τοι λέγειν ἔμοιγε φαίνεσθον πάνυ:<br>πλὴν ἓν μόνον δέδοικα."}, {"st": null, "sp": "Χρεμύλος", "t": "φράζε τοῦ πέρι;"}, {"st": "200", "sp": "Πλοῦτος", "t": "ὅπως ἐγὼ τὴν δύναμιν ἣν ὑμεῖς φατε<br>ἔχειν με, ταύτης δεσπότης γενήσομαι."}, {"st": null, "sp": "Χρεμύλος", "t": "νὴ τὸν Δί᾽ ἀλλὰ καὶ λέγουσι πάντες ὡς<br>δειλότατόν ἐσθ᾽ ὁ Πλοῦτος."}, {"st": null, "sp": "Πλοῦτος", "t": "ἥκιστ᾽, ἀλλά με<br>τοιχωρύχος τις διέβαλ᾽. ἐσδὺς γάρ ποτε<br>οὐκ εἶχεν ἐς τὴν οἰκίαν οὐδὲν λαβεῖν,<br>εὑρὼν ἁπαξάπαντα κατακεκλῃμένα:<br>εἶτ᾽ ὠνόμασέ μου τὴν πρόνοιαν δειλίαν."}, {"st": null, "sp": "Χρεμύλος", "t": "μή νυν μελέτω σοι μηδέν: ὡς ἐὰν γένῃ<br>ἀνὴρ πρόθυμος αὐτὸς ἐς τὰ πράγματα,<br>βλέποντ᾽ ἀποδείξω σ᾽ ὀξύτερον τοῦ Λυγκέως."}, {"st": null, "sp": "Πλοῦτος", "t": "πῶς οὖν δυνήσει τοῦτο δρᾶσαι θνητὸς ὤν;"}, {"st": null, "sp": "Χρεμύλος", "t": "ἔχω τιν᾽ ἀγαθὴν ἐλπίδ᾽ ἐξ ὧν εἶπέ μοι<br>ὁ Φοῖβος αὐτὸς Πυθικὴν σείσας δάφνην."}, {"st": null, "sp": "Πλοῦτος", "t": "κἀκεῖνος οὖν σύνοιδε ταῦτα;"}, {"st": null, "sp": "Χρεμύλος", "t": "φήμ᾽ ἐγώ."}, {"st": "215", "sp": "Πλοῦτος", "t": "ὁρᾶτε."}, {"st": null, "sp": "Χρεμύλος", "t": "μὴ φρόντιζε μηδὲν ὦγαθέ.<br>ἐγὼ γάρ, εὖ τοῦτ᾽ ἴσθι, κεἰ δεῖ μ᾽ ἀποθανεῖν,<br>αὐτὸς διαπράξω ταῦτα."}, {"st": null, "sp": "Καρίων", "t": "κἂν βούλῃ γ᾽, ἐγώ."}, {"st": null, "sp": "Χρεμύλος", "t": "πολλοὶ δ᾽ ἔσονται χἄτεροι νῷν ξύμμαχοι,<br>ὅσοις δικαίοις οὖσιν οὐκ ἦν ἄλφιτα."}, {"st": "220", "sp": "Πλοῦτος", "t": "παπαῖ πονηρούς γ᾽ εἶπας ἡμῖν συμμάχους."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐκ ἤν γε πλουτήσωσιν ἐξ ἀρχῆς πάλιν.<br>ἀλλ᾽ ἴθι σὺ μὲν ταχέως δραμών —"}, {"st": null, "sp": "Καρίων", "t": "τί δρῶ; λέγε."}, {"st": null, "sp": "Χρεμύλος", "t": "τοὺς ξυγγεώργους κάλεσον, εὑρήσεις δ᾽ ἴσως<br>ἐν τοῖς ἀγροῖς αὐτοὺς ταλαιπωρουμένους,<br>ὅπως ἂν ἴσον ἕκαστος ἐνταυθοῖ παρὼν<br>ἡμῖν μετάσχῃ τοῦδε τοῦ Πλούτου μέρος."}, {"st": null, "sp": "Καρίων", "t": "καὶ δὴ βαδίζω: τουτοδὶ τὸ κρεᾴδιον<br>τῶν ἔνδοθέν τις εἰσενεγκάτω λαβών."}, {"st": null, "sp": "Χρεμύλος", "t": "ἐμοὶ μελήσει τοῦτό γ᾽: ἀλλ᾽ ἀνύσας τρέχε.<br>σὺ δ᾽ ὦ κράτιστε Πλοῦτε πάντων δαιμόνων<br>εἴσω μετ᾽ ἐμοῦ δεῦρ᾽ εἴσιθ᾽: ἡ γὰρ οἰκία<br>αὕτη ‘στὶν ἣν δεῖ χρημάτων σε τήμερον<br>μεστὴν ποιῆσαι καὶ δικαίως κἀδίκως."}, {"st": null, "sp": "Πλοῦτος", "t": "ἀλλ᾽ ἄχθομαι μὲν εἰσιὼν νὴ τοὺς θεοὺς<br>εἰς οἰκίαν ἑκάστοτ᾽ ἀλλοτρίαν πάνυ:<br>ἀγαθὸν γὰρ ἀπέλαυσ᾽ οὐδὲν αὐτοῦ πώποτε.<br>ἢν μὲν γὰρ ὡς φειδωλὸν εἰσελθὼν τύχω,<br>εὐθὺς κατώρυξέν με κατὰ τῆς γῆς κάτω:<br>κἄν τις προσέλθῃ χρηστὸς ἄνθρωπος φίλος<br>αἰτῶν λαβεῖν τι σμικρὸν ἀργυρίδιον,<br>ἔξαρνός ἐστι μηδ᾽ ἰδεῖν με πώποτε.<br>ἢν δ᾽ ὡς παραπλῆγ᾽ ἄνθρωπον εἰσελθὼν τύχω,<br>πόρναισι καὶ κύβοισι παραβεβλημένος<br>γυμνὸς θύραζ᾽ ἐξέπεσον ἐν ἀκαρεῖ χρόνου."}, {"st": "245", "sp": "Χρεμύλος", "t": "μετρίου γὰρ ἀνδρὸς οὐκ ἐπέτυχες πώποτε.<br>ἐγὼ δὲ τούτου τοῦ τρόπου πώς εἰμ᾽ ἀεί,<br>χαίρω τε γὰρ φειδόμενος ὡς οὐδεὶς ἀνὴρ<br>πάλιν τ᾽ ἀναλῶν, ἡνίκ᾽ ἂν τούτου δέῃ.<br>ἀλλ᾽ εἰσίωμεν, ὡς ἰδεῖν σε βούλομαι<br>καὶ τὴν γυναῖκα καὶ τὸν υἱὸν τὸν μόνον,<br>ὃν ἑγὼ φιλῶ μάλιστα μετὰ σέ."}, {"st": null, "sp": "Πλοῦτος", "t": "πείθομαι."}, {"st": null, "sp": "Χρεμύλος", "t": "τί γὰρ ἄν τις οὐχὶ πρὸς σὲ τἀληθῆ λέγοι;"}, {"st": null, "sp": "Καρίων", "t": "ὦ πολλὰ δὴ τῷ δεσπότῃ ταὐτὸν θύμον φαγόντες,<br>ἄνδρες φίλοι καὶ δημόται καὶ τοῦ πονεῖν ἐρασταί,<br>ἴτ᾽ ἐγκονεῖτε σπεύδεθ᾽, ὡς ὁ καιρὸς οὐχὶ μέλλειν,<br>ἀλλ᾽ ἔστ᾽ ἐπ᾽ αὐτῆς τῆς ἀκμῆς, ᾗ δεῖ παρόντ᾽ ἀμύνειν."}, {"st": null, "sp": "Χορός", "t": "οὔκουν ὁρᾷς ὁρμωμένους ἡμᾶς πάλαι προθύμως,<br>ὡς εἰκός ἐστιν ἀσθενεῖς γέροντας ἄνδρας ἤδη;<br>σὺ δ᾽ ἀξιοῖς ἴσως με θεῖν, πρὶν ταῦτα καὶ φράσαι μοι<br>ὅτου χάριν μ᾽ ὁ δεσπότης ὁ σὸς κέκληκε δῦρο."}, {"st": null, "sp": "Καρίων", "t": "οὔκουν πάλαι δήπου λέγω; σὺ δ᾽ αὐτὸς οὐκ ἀκούεις.<br>ὁ δεσπότης γάρ φησιν ὑμᾶς ἡδέως ἅπαντας<br>ψυχροῦ βίου καὶ δυσκόλου ζήσειν ἀπαλλαγέντας."}, {"st": null, "sp": "Χορός", "t": "ἔστιν δὲ δὴ τί καὶ πόθεν τὸ πρᾶγμα τοῦθ᾽ ὅ φησιν;"}, {"st": "265", "sp": "Καρίων", "t": "ἔχων ἀφῖκται δεῦρο πρεσβύτην τιν᾽ ὦ πόνηροι<br>ῥυπῶντα κυφὸν ἄθλιον ῥυσὸν μαδῶντα νωδόν:<br>οἶμαι δὲ νὴ τὸν οὐρανὸν καὶ ψωλὸν αὐτὸν εἶναι."}, {"st": null, "sp": "Χορός", "t": "ὦ χρυσὸν ἀγγείλας ἐπῶν πῶς φῄς; πάλιν φράσον μοι.<br>δηλοῖς γὰρ αὐτὸν σωρὸν ἥκειν χρημάτων ἔχοντα."}, {"st": "270", "sp": "Καρίων", "t": "πρεσβυτικῶν μὲν οὖν κακῶν ἔγωγ᾽ ἔχοντα σωρόν."}, {"st": null, "sp": "Χορός", "t": "μῶν ἀξιοῖς φενακίσας ἔπειτ᾽ ἀπαλλαγῆναι<br>ἀζήμιος, καὶ ταῦτ᾽ ἐμοῦ βακτηρίαν ἔχοντος;"}, {"st": null, "sp": "Καρίων", "t": "πάντως γὰρ ἄνθρωπον φύσει τοιοῦτον ἐς τὰ πάντα<br>ἡγεῖσθέ μ᾽ εἶναι κοὐδὲν ἂν νομίζεθ᾽ ὑγιὲς εἰπεῖν;"}, {"st": "275", "sp": "Χορός", "t": "ὡς σεμνὸς οὑπίτριπτος: αἱ κνῆμαι δέ σου βοῶσιν<br>‘ἰοὺ ἰού,’ τὰς χοίνικας καὶ τὰς πέδας ποθοῦσαι."}, {"st": null, "sp": "Καρίων", "t": "ἐν τῇ σορῷ νυνὶ λαχὸν τὸ γράμμα σου δικάζειν,<br>σὺ δ᾽ οὐ βαδίζεις, ὁ δὲ Χάρων τὸ ξύμβολον δίδωσιν."}, {"st": null, "sp": "Χορός", "t": "διαρραγείης, ὡς μόθων εἶ καὶ φύσει κόβαλος,<br>ὅστις φενακίζεις, φράσαι δ᾽ οὔπω τέτληκας ἡμῖν,<br>οἳ πολλὰ μοχθήσαντες οὐκ οὔσης σχολῆς προθύμως<br>δεῦρ᾽ ἤλθομεν, πολλῶν θύμων ῥίζας διεκπερῶντες."}, {"st": null, "sp": "Καρίων", "t": "ἀλλ᾽ οὐκέτ᾽ ἂν κρύψαιμι. τὸν Πλοῦτον γὰρ ὦνδρες ἥκει<br>ἄγων ὁ δεσπότης, ὃς ὑμᾶς πλουσίους ποιήσει."}, {"st": null, "sp": "Χορός", "t": "ὄντως γὰρ ἔστι πλουσίοις ἡμῖν ἅπασιν εἶναι;"}, {"st": null, "sp": "Καρίων", "t": "νὴ τοὺς θεοὺς Μίδαις μὲν οὖν, ἢν ὦτ᾽ ὄνου λάβητε."}, {"st": null, "sp": "Χορός", "t": "ὡς ἥδομαι καὶ τέρπομαι καὶ βούλομαι χορεῦσαι<br>ὑφ᾽ ἡδονῆς, εἴπερ λέγεις ὄντως σὺ ταῦτ᾽ ἀληθῆ."}, {"st": "290", "sp": "Καρίων", "t": "καὶ μὴν ἐγὼ βουλήσομαι θρεττανελὸ τὸν Κύκλωπα<br>μιμούμενος καὶ τοῖν ποδοῖν ὡδὶ παρενσαλεύων<br>ὑμᾶς ἄγειν. ἀλλ᾽ εἶα τέκεα θαμίν᾽ ἐπαναβοῶντες<br>βληχώμενοί τε προβατίων<br>αἰγῶν τε κιναβρώντων μέλη<br>ἕπεσθ᾽ ἀπεψωλημένοι: τράγοι δ᾽ ἀκρατιεῖσθε."}, {"st": null, "sp": "Καρίων", "t": "ἡμεῖς δέ γ᾽ αὖ ζητήσομεν θρεττανελὸ τὸν Κύκλωπα<br>βληχώμενοι, σὲ τουτονὶ πεινῶντα καταλαβόντες,<br>πήραν ἔχοντα λάχανά τ᾽ ἄγρια δροσερά, κραιπαλῶντα<br>ἡγούμενον τοῖς προβατίοις,<br>εἰκῇ δὲ καταδαρθόντα που<br>μέγαν λαβόντες ἡμμένον σφηκίσκον ἐκτυφλῶσαι."}, {"st": null, "sp": "Καρίων", "t": "ἐγὼ δὲ τὴν Κίρκην γε τὴν τὰ φάρμακ᾽ ἀνακυκῶσαν,<br>ἣ τοὺς ἑταίρους τοῦ Φιλωνίδου ποτ᾽ ἐν Κορίνθῳ<br>ἔπεισεν ὡς ὄντας κάπρους<br>μεμαγμένον σκῶρ ἐσθίειν, αὐτὴ δ᾽ ἔματτεν αὐτοῖς,<br>μιμήσομαι πάντας τρόπους:<br>ὑμεῖς δὲ γρυλίζοντες ὑπὸ φιληδίας<br>ἕπεσθε μητρὶ χοῖροι."}, {"st": null, "sp": "Καρίων", "t": "οὐκοῦν σε τὴν Κίρκην γε τὴν τὰ φάρμακ᾽ ἀνακυκῶσαν<br>καὶ μαγγανεύουσαν μολύνουσάν τε τοὺς ἑταίρους<br>λαβόντες ὑπὸ φιληδίας<br>τὸν Λαρτίου μιμούμενοι τῶν ὄρχεων κρεμῶμεν,<br>μινθώσομέν θ᾽ ὥσπερ τράγου<br>τὴν ῥῖνα: σὺ δ᾽ Ἀρίστυλλος ὑποχάσκων ἐρεῖς,<br>ἕπεσθε μητρὶ χοῖροι."}, {"st": null, "sp": "Καρίων", "t": "ἀλλ᾽ εἶα νῦν τῶν σκωμμάτων ἀπαλλαγέντες ἤδη<br>ὑμεῖς ἐπ᾽ ἄλλ᾽ εἶδος τρέπεσθ᾽,<br>ἐγὼ δ᾽ ἰὼν ἤδη λάθρᾳ<br>βουλήσομαι τοῦ δεσπότου<br>λαβών τιν᾽ ἄρτον καὶ κρέας<br>μασώμενος τὸ λοιπὸν οὕτω τῷ κόπῳ ξυνεῖναι."}, {"st": null, "sp": "Χρεμύλος", "t": "χαίρειν μὲν ὑμᾶς ἐστιν ὦνδρες δημόται<br>ἀρχαῖον ἤδη προσαγορεύειν καὶ σαπρόν:<br>ἀσπάζομαι δ᾽ ὁτιὴ προθύμως ἥκετε<br>καὶ συντεταμένως κοὐ κατεβλακευμένως.<br>ὅπως δέ μοι καὶ τἄλλα συμπαραστάται<br>ἔσεσθε καὶ σωτῆρες ὄντως τοῦ θεοῦ."}, {"st": null, "sp": "Χορός", "t": "θάρρει: βλέπειν γὰρ ἄντικρυς δόξεις μ᾽ Ἄρη.<br>δεινὸν γὰρ εἰ τριωβόλου μὲν οὕνεκα<br>ὠστιζόμεσθ᾽ ἑκάστοτ᾽ ἐν τἠκκλησίᾳ,<br>αὐτὸν δὲ τὸν Πλοῦτον παρείην τῳ λαβεῖν."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ μὴν ὁρῶ καὶ Βλεψίδημον τουτονὶ<br>προσιόντα: δῆλος δ᾽ ἐστὶν ὅτι τοῦ πράγματος<br>ἀκήκοέν τι τῇ βαδίσει καὶ τῷ τάχει."}, {"st": "335", "sp": "Βλεψίδημος", "t": "τί ἂν οὖν τὸ πρᾶγμ᾽ εἴη; πόθεν καὶ τίνι τρόπῳ<br>Χρεμύλος πεπλούτηκ᾽ ἐξαπίνης; οὐ πείθομαι.<br>καίτοι λόγος γ᾽ ἦν νὴ τὸν Ἡρακλέα πολὺς<br>ἐπὶ τοῖσι κουρείοισι τῶν καθημένων,<br>ὡς ἐξαπίνης ἀνὴρ γεγένηται πλούσιος.<br>ἔστιν δέ μοι τοῦτ᾽ αὐτὸ θαυμάσιον, ὅπως<br>χρηστόν τι πράττων τοὺς φίλους μεταπέμπεται.<br>οὔκουν ἐπιχώριόν γε πρᾶγμ᾽ ἐργάζεται."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλ᾽ οὐδὲν ἀποκρύψας ἐρῶ: νὴ τοὺς θεοὺς<br>ὦ Βλεψίδημ᾽ ἄμεινον ἢ χθὲς πράττομεν,<br>ὥστε μετέχειν ἔξεστιν: εἶ γὰρ τῶν φίλων."}, {"st": null, "sp": "Βλεψίδημος", "t": "γέγονας δ᾽ ἀληθῶς, ὡς λέγουσι, πλούσιος;"}, {"st": null, "sp": "Χρεμύλος", "t": "ἔσομαι μὲν οὖν αὐτίκα μάλ᾽, ἢν θεὸς θέλῃ.<br>ἔνι γάρ τις ἔνι κίνδυνος ἐν τῷ πράγματι."}, {"st": null, "sp": "Βλεψίδημος", "t": "ποῖός τις;"}, {"st": null, "sp": "Χρεμύλος", "t": "οἷος;"}, {"st": null, "sp": "Βλεψίδημος", "t": "λέγ᾽ ἀνύσας ὅ τι φῄς ποτε."}, {"st": "350", "sp": "Χρεμύλος", "t": "ἢν μὲν κατορθώσωμεν, εὖ πράττειν ἀεί:<br>ἢν δὲ σφαλῶμεν, ἐπιτετρῖφθαι τὸ παράπαν."}, {"st": null, "sp": "Βλεψίδημος", "t": "τουτὶ πονηρὸν φαίνεται τὸ φορτίον<br>καί μ᾽ οὐκ ἀρέσκει. τό τε γὰρ ἐξαίφνης ἄγαν<br>οὕτως ὑπερπλουτεῖν τό τ᾽ αὖ δεδοικέναι<br>πρὸς ἀνδρὸς οὐδὲν ὑγιές ἐστ᾽ εἰργασμένου."}, {"st": null, "sp": "Χρεμύλος", "t": "πῶς οὐδὲν ὑγιές;"}, {"st": null, "sp": "Βλεψίδημος", "t": "εἴ τι κεκλοφὼς νὴ Δία<br>ἐκεῖθεν ἥκεις ἀργύριον ἢ χρυσίον<br>παρὰ τοῦ θεοῦ, κἄπειτ᾽ ἴσως σοι μεταμέλει."}, {"st": null, "sp": "Χρεμύλος", "t": "Ἄπολλον ἀποτρόπαιε μὰ Δί᾽ ἐγὼ μὲν οὔ."}, {"st": "360", "sp": "Βλεψίδημος", "t": "παῦσαι φλυαρῶν ὦγάθ᾽: οῖδα γὰρ σαφῶς."}, {"st": null, "sp": "Χρεμύλος", "t": "σὺ μηδὲν εἰς ἔμ᾽ ὑπονόει τοιουτονί."}, {"st": null, "sp": "Βλεψίδημος", "t": "φεῦ,<br>ὡς οὐδὲν ἀτεχνῶς ὑγιές ἐστιν οὐδενός,<br>ἀλλ᾽ εἰσὶ τοῦ κέρδους ἅπαντες ἥττονες."}, {"st": null, "sp": "Χρεμύλος", "t": "οὔ τοι μὰ τὴν Δήμητρ᾽ ὑγιαίνειν μοι δοκεῖς."}, {"st": "365", "sp": "Βλεψίδημος", "t": "ὡς πολὺ μεθέστηχ᾽ ὧν πρότερον εἶχεν τρόπων."}, {"st": null, "sp": "Χρεμύλος", "t": "μελαγχολᾷς ὦνθρωπε νὴ τὸν οὐρανόν."}, {"st": null, "sp": "Βλεψίδημος", "t": "ἀλλ᾽ οὐδὲ τὸ βλέμμ᾽ αὐτὸ κατὰ χώραν ἔχει,<br>ἀλλ᾽ ἐστὶν ἐπίδηλόν τι πεπανουργηκότι."}, {"st": null, "sp": "Χρεμύλος", "t": "σὺ μὲν οἶδ᾽ ὃ κρώζεις: ὡς ἐμοῦ τι κεκλοφότος<br>ζητεῖς μεταλαβεῖν."}, {"st": null, "sp": "Βλεψίδημος", "t": "μεταλαβεῖν ζητῶ; τίνος;"}, {"st": null, "sp": "Χρεμύλος", "t": "τὸ δ᾽ ἐστὶν οὐ τοιοῦτον ἀλλ᾽ ἑτέρως ἔχον."}, {"st": null, "sp": "Βλεψίδημος", "t": "μῶν οὐ κέκλοφας ἀλλ᾽ ἥρπακας;"}, {"st": null, "sp": "Χρεμύλος", "t": "κακοδαιμονᾷς."}, {"st": null, "sp": "Βλεψίδημος", "t": "ἀλλ᾽ οὐδὲ μὴν ἀπεστέρηκάς γ᾽ οὐδένα;"}, {"st": null, "sp": "Χρεμύλος", "t": "ου᾽ δῆτ᾽ ἔγωγ᾽."}, {"st": null, "sp": "Βλεψίδημος", "t": "ὦ Ἡράκλεις, φέρε ποῖ τις ἂν<br>τράποιτο; τἀληθὲς γὰρ οὐκ ἐθέλει φράσαι."}, {"st": null, "sp": "Χρεμύλος", "t": "κατηγορεῖς γὰρ πρὶν μαθεῖν τὸ πρᾶγμά μου."}, {"st": null, "sp": "Βλεψίδημος", "t": "ὦ τᾶν ἐγώ τοι τοῦτ᾽ ἀπὸ σμικροῦ πάνυ<br>ἐθέλω διαπρᾶξαι πρὶν πυθέσθαι τὴν πόλιν,<br>τὸ στόμ᾽ ἐπιβύσας κέρμασιν τῶν ῥητόρων."}, {"st": "380", "sp": "Χρεμύλος", "t": "καὶ μὴν φίλως γ᾽ ἄν μοι δοκεῖς νὴ τοὺς θεοὺς<br>τρεῖς μνᾶς ἀναλώσας λογίσασθαι δώδεκα."}, {"st": null, "sp": "Βλεψίδημος", "t": "ὁρῶ τιν᾽ ἐπὶ τοῦ βήματος καθεδούμενον<br>ἱκετηρίαν ἔχοντα μετὰ τῶν παιδίων<br>καὶ τῆς γυναικός, κου᾽ διοίσοντ᾽ ἄντικρυς<br>τῶν Ἡρακλειδῶν οὐδ᾽ ὁτιοῦν τῶν Παμφίλου."}, {"st": null, "sp": "Χρεμύλος", "t": "οὒκ ὦ κακόδαιμον, ἀλλὰ τοὺς χρηστοὺς μόνους<br>ἔγωγε καὶ τοὺς δεξιοὺς καὶ σώφρονας<br>ἀπαρτὶ πλουτῆσαι ποιήσω."}, {"st": null, "sp": "Βλεψίδημος", "t": "τί σὺ λέγεις;<br>οὕτω πάνυ πολλὰ κέκλοφας;"}, {"st": null, "sp": "Χρεμύλος", "t": "οἴμοι τῶν κακῶν,<br>ἀπολεῖς."}, {"st": null, "sp": "Βλεψίδημος", "t": "σὺ μὲν οὖν σεαυτόν, ὥς γ᾽ ἐμοὶ δοκεῖς."}, {"st": null, "sp": "Χρεμύλος", "t": "ου᾽ δῆτ᾽, ἐπεὶ τὸν Πλοῦτον ὦ μόχθηρε σὺ<br>ἔχω."}, {"st": null, "sp": "Βλεψίδημος", "t": "σὺ Πλοῦτον; ποῖον;"}, {"st": null, "sp": "Χρεμύλος", "t": "αὐτὸν τὸν θεόν."}, {"st": null, "sp": "Βλεψίδημος", "t": "καὶ ποῦ ‘στιν;"}, {"st": null, "sp": "Χρεμύλος", "t": "ἔνδον."}, {"st": null, "sp": "Βλεψίδημος", "t": "ποῦ;"}, {"st": null, "sp": "Χρεμύλος", "t": "παρ᾽<br>ἐμοί."}, {"st": null, "sp": "Βλεψίδημος", "t": "παρὰ σοί;"}, {"st": null, "sp": "Χρεμύλος", "t": "πάνυ."}, {"st": null, "sp": "Βλεψίδημος", "t": "οὐκ ἐς κόρακας; Πλοῦτος παρὰ σοί;"}, {"st": null, "sp": "Χρεμύλος", "t": "νὴ τοὺς θεούς."}, {"st": "395", "sp": "Βλεψίδημος", "t": "λὲγεις ἀληθῆ;"}, {"st": null, "sp": "Χρεμύλος", "t": "φημί."}, {"st": null, "sp": "Βλεψίδημος", "t": "πρὸς τῆς Ἑστίας;"}, {"st": null, "sp": "Χρεμύλος", "t": "νὴ τὸν Ποσειδῶ."}, {"st": null, "sp": "Βλεψίδημος", "t": "τὸν θαλάττιον λέγεις;"}, {"st": null, "sp": "Χρεμύλος", "t": "εἰ δ᾽ ἔστιν ἕτερός τις Ποσειδῶν, τὸν ἕτερον."}, {"st": null, "sp": "Βλεψίδημος", "t": "εἶτ᾽ οὐ διαπέμπεις καὶ πρὸς ἡμᾶς τοὺς φίλους;"}, {"st": null, "sp": "Χρεμύλος", "t": "οὐκ ἔστι πω τὰ πράγματ᾽ ἐν τούτῳ."}, {"st": null, "sp": "Βλεψίδημος", "t": "τί φῄς;<br>οὐ τῷ μεταδοῦναι;"}, {"st": null, "sp": "Χρεμύλος", "t": "μὰ Δία. δεῖ γὰρ πρῶτα"}, {"st": null, "sp": "Βλεψίδημος", "t": "τί;"}, {"st": null, "sp": "Χρεμύλος", "t": "βλέψαι ποιῆσαι νώ —"}, {"st": null, "sp": "Βλεψίδημος", "t": "τίνα βλέψαι; φράσον."}, {"st": null, "sp": "Χρεμύλος", "t": "τὸν Πλοῦτον ὥσπερ πρότερον ἑνί γέ τῳ τρόπῳ."}, {"st": null, "sp": "Βλεψίδημος", "t": "τυφλὸς γὰρ ὄντως ἐστί;"}, {"st": null, "sp": "Χρεμύλος", "t": "νὴ τὸν οὐρανόν."}, {"st": null, "sp": "Βλεψίδημος", "t": "οὐκ ἐτὸς ἄρ᾽ ὡς ἔμ᾽ ἦλθεν οὐδεπώποτε."}, {"st": "405", "sp": "Χρεμύλος", "t": "ἀλλ᾽ ἢν θεοὶ θέλωσι, νῦν ἀφίξεται."}, {"st": null, "sp": "Βλεψίδημος", "t": "οὔκουν ἰατρὸν εἰσάγειν ἐχρῆν τινά;"}, {"st": null, "sp": "Χρεμύλος", "t": "τίς δῆτ᾽ ἰατρός ἐστι νῦν ἐν τῇ πόλει;<br>οὔτε γὰρ ὁ μισθὸς οὐδὲν ἔστ᾽ οὔθ᾽ ἡ τέχνη."}, {"st": null, "sp": "Βλεψίδημος", "t": "σκοπῶμεν."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλ᾽ οὐκ ἔστιν."}, {"st": null, "sp": "Βλεψίδημος", "t": "οὐδ ἐμοὶ δοκεῖ."}, {"st": "410", "sp": "Χρεμύλος", "t": "μὰ Δί᾽ ἀλλ᾽ ὅπερ πάλαι παρεσκευαζόμην<br>ἐγώ, κατακλίνειν αὐτὸν εἰς Ἀσκληπιοῦ<br>κράτιστόν ἐστι."}, {"st": null, "sp": "Βλεψίδημος", "t": "πολὺ μὲν οὖν νὴ τοὺς θεούς.<br>μή νυν διάτριβ᾽ ἀλλ᾽ ἄνυε πράττων ἕν γέ τι."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ δὴ βαδίζω."}, {"st": null, "sp": "Βλεψίδημος", "t": "σπεῦδέ νυν."}, {"st": null, "sp": "Χρεμύλος", "t": "τοῦτ᾽ αὐτὸ δρῶ."}, {"st": "415", "sp": "Πενία", "t": "ὦ θερμὸν ἔργον κἀνόσιον καὶ παράνομον<br>τολμῶντε δρᾶν ἀνθρωπαρίω κακοδαίμονε —<br>ποῖ ποῖ; τί φεύγετον; οὐ μενεῖτον;"}, {"st": null, "sp": "Βλεψίδημος", "t": "Ἡράκλεις."}, {"st": null, "sp": "Πενία", "t": "ἐγὼ γὰρ ὑμᾶς ἐξολῶ κακοὺς κακῶς:<br>τόλμημα γὰρ τολμᾶτον οὐκ ἀνασχετόν,<br>ἀλλ᾽ οἷον οὐδεὶς ἄλλος οὐδεπώποτε<br>οὔτε θεὸς οὔτ᾽ ἄνθρωπος: ὥστ᾽ ἀπολώλατον."}, {"st": null, "sp": "Χρεμύλος", "t": "σὺ δ᾽ εἶ τίς; ὠχρὰ μὲν γὰρ εἶναί μοι δοκεῖς."}, {"st": null, "sp": "Βλεψίδημος", "t": "ἴσως Ἐρινύς ἐστιν ἐκ τραγῳδίας:<br>βλέπει γέ τοι μανικόν τι καὶ τραγῳδικόν."}, {"st": "425", "sp": "Χρεμύλος", "t": "ἀλλ᾽ οὐκ ἔχει γὰρ δᾷδας."}, {"st": null, "sp": "Βλεψίδημος", "t": "οὐκοῦν κλαύσεται."}, {"st": null, "sp": "Πενία", "t": "ὄιεσθε δ᾽ εἶναι τίνα με;"}, {"st": null, "sp": "Χρεμύλος", "t": "πανδοκεύτριαν<br>ἢ λεκιθόπωλιν. οὐ γὰρ ἂν τοσουτονὶ<br>ἀνέκραγες ἡμῖν οὐδὲν ἠδικημένη."}, {"st": null, "sp": "Πενία", "t": "ἄληθες; οὐ γὰρ δεινότατα δεδράκατον<br>ζητοῦντες ἐκ πάσης με χώρας ἐκβαλεῖν;"}, {"st": null, "sp": "Χρεμύλος", "t": "οὔκουν ὑπόλοιπον τὸ βάραθρόν σοι γίγνεται;<br>ἀλλ᾽ ἥτις εἶ λέγειν σ᾽ ἐχρῆν αὐτίκα μάλα."}, {"st": null, "sp": "Πενία", "t": "ἣ σφὼ ποιήσω τήμερον δοῦναι δίκην<br>ἀνθ᾽ ὧν ἐμὲ ζητεῖτον ἐνθένδ᾽ ἀφανίσαι."}, {"st": "435", "sp": "Βλεψίδημος", "t": "ἆρ᾽ ἐστὶν ἡ καπηλὶς ἡκ τῶν γειτόνων,<br>ἣ ταῖς κοτύλαις ἀεί με διαλυμαίνεται;"}, {"st": null, "sp": "Πενία", "t": "Πενία μὲν οὖν, ἣ σφῷν ξυνοικῶ πόλλ᾽ ἔτη."}, {"st": null, "sp": "Βλεψίδημος", "t": "ἄναξ Ἄπολλον καὶ θεοί, ποῖ τις φύγῃ;"}, {"st": null, "sp": "Χρεμύλος", "t": "οὗτος τί δρᾷς; ὦ δειλότατον σὺ θηρίον:<br>οὐ παραμενεῖς;"}, {"st": null, "sp": "Βλεψίδημος", "t": "ἥκιστα πάντων."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐ μενεῖς;<br>ἀλλ᾽ ἄνδρε δύο γυναῖκα φεύγομεν μίαν;"}, {"st": null, "sp": "Βλεψίδημος", "t": "Πενία γάρ ἐστιν ὦ πόνηρ᾽, ἧς οὐδαμοῦ<br>οὐδὲν πέφυκε ζῷον ἐξωλέστερον."}, {"st": null, "sp": "Χρεμύλος", "t": "στῆθ᾽, ἀντιβολῶ σε, στῆθι."}, {"st": null, "sp": "Βλεψίδημος", "t": "μὰ Δί᾽ ἐγὼ μὲν οὔ."}, {"st": "445", "sp": "Χρεμύλος", "t": "καὶ μὴν λέγω, δεινότατον ἔργον παρὰ πολὺ<br>ἔργων ἁπάντων ἐργασόμεθ᾽, εἰ τὸν θεὸν<br>ἔρημον ἀπολιπόντε ποι φευξούμεθα<br>τηνδὶ δεδιότε, μηδὲ διαμαχούμεθα."}, {"st": null, "sp": "Βλεψίδημος", "t": "ποίοις ὅπλοισιν ἢ δυνάμει πεποιθότες;<br>ποῖον γὰρ οὐ θώρακα, ποίαν δ᾽ ἀσπίδα<br>οὐκ ἐνέχυρον τίθησιν ἡ μιαρωτάτη;"}, {"st": null, "sp": "Χρεμύλος", "t": "θάρρει: μόνος γὰρ ὁ θεὸς οὗτος οἶδ᾽ ὅτι<br>τροπαῖον ἂν στήσαιτο τῶν ταύτης τρόπων."}, {"st": null, "sp": "Πενία", "t": "γρύζειν δὲ καὶ τολμᾶτον ὦ καθάρματε,<br>ἐπ᾽ αὐτοφώρῳ δεινὰ δρῶντ᾽ εἰλημμένω;"}, {"st": null, "sp": "Χρεμύλος", "t": "σὺ δ᾽ ὦ κάκιστ᾽ ἀπολουμένη τί λοιδορεῖ<br>ἡμῖν προσελθοῦσ᾽ οὐδ᾽ ὁτιοῦν ἀδικουμένη;"}, {"st": null, "sp": "Πενία", "t": "οὐδὲν γὰρ ὦ πρὸς τῶν θεῶν νομίζετε<br>ἀδικεῖν με τὸν Πλοῦτον ποιεῖν πειρωμένω<br>βλέψαι πάλιν;"}, {"st": null, "sp": "Χρεμύλος", "t": "τί οὖν ἀδικοῦμεν τοῦτό σε,<br>εἰ πᾶσιν ἀνθρώποισιν ἐκπορίζομεν<br>ἀγαθόν;"}, {"st": null, "sp": "Πενία", "t": "τί δ᾽ ἂν ὑμεῖς ἀγαθὸν ἐξεύροιθ᾽;"}, {"st": null, "sp": "Χρεμύλος", "t": "ὅ τι;<br>σὲ πρῶτον ἐκβαλόντες ἐκ τῆς Ἑλλάδος."}, {"st": null, "sp": "Πενία", "t": "ἔμ᾽ ἐκβαλόντες; καὶ τί ἂν νομίζετον<br>κακὸν ἐργάσασθαι μεῖζον ἀνθρώπους;"}, {"st": null, "sp": "Χρεμύλος", "t": "ὅ τι;<br>εἰ τοῦτο δρᾶν μέλλοντες ἐπιλαθοίμεθα."}, {"st": null, "sp": "Πενία", "t": "καὶ μὴν περὶ τούτου σφῷν ἐθέλω δοῦναι λόγον<br>τὸ πρῶτον αὐτοῦ: κἂν μὲν ἀποφήνω μόνην<br>ἀγαθῶν ἁπάντων οὖσαν αἰτίαν ἐμὲ<br>ὑμῖν δι᾽ ἐμέ τε ζῶντας ὑμᾶς: εἰ δὲ μή,<br>ποιεῖτον ἤδη τοῦθ᾽ ὅ τι ἂν ὑμῖν δοκῇ."}, {"st": null, "sp": "Χρεμύλος", "t": "ταυτὶ σὺ τολμᾷς ὦ μιαρωτάτη λέγειν;"}, {"st": null, "sp": "Πενία", "t": "καὶ σύ γε διδάσκου: πάνυ γὰρ οἶμαι ῥᾳδίως<br>ἅπανθ᾽ ἁμαρτάνοντά σ᾽ ἀποδείξειν ἐγώ,<br>εἰ τοὺς δικαίους φῂς ποιήσειν πλουσίους."}, {"st": null, "sp": "Χρεμύλος", "t": "ὦ τύμπανα καὶ κύφωνες οὐκ ἀρήξετε;"}, {"st": null, "sp": "Πενία", "t": "οὐ δεῖ σχετλιάζειν καὶ βοᾶν πρὶν ἂν μάθῃς."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ τίς δύναιτ᾽ ἂν μὴ βοᾶν ‘ἰοὺ ἰοὺ’<br>τοιαῦτ᾽ ἀκούων;"}, {"st": null, "sp": "Πενία", "t": "ὅστις ἐστὶν εὖ φρονῶν."}, {"st": "480", "sp": "Χρεμύλος", "t": "τί δῆτά σοι τίμημ᾽ ἐπιγράψω τῇ δίκῃ,<br>ἐὰν ἁλῷς;"}, {"st": null, "sp": "Πενία", "t": "ὅ τι σοι δοκεῖ."}, {"st": null, "sp": "Χρεμύλος", "t": "καλῶς λέγεις."}, {"st": null, "sp": "Πενία", "t": "τὸ γὰρ αὔτ᾽, ἐὰν ἡττᾶσθε, καὶ σφὼ δεῖ παθεῖν."}, {"st": null, "sp": "Χρεμύλος", "t": "ἱκανοὺς νομίζεις δῆτα θανάτους εἴκοσιν;"}, {"st": null, "sp": "Βλεψίδημος", "t": "ταύτῃ γε: νῷν δὲ δὔ ἀποχρήσουσιν μόνω."}, {"st": "485", "sp": "Πενία", "t": "οὐκ ἂν φθάνοιτον τοῦτο πράττοντ᾽, ἢ τί γ᾽ ἂν<br>ἔχοι τις ἂν δίκαιον ἀντειπεῖν ἔτι;"}, {"st": null, "sp": "Χορός", "t": "ἀλλ᾽ ἤδη χρῆν τι λέγειν ὑμᾶς σοφὸν ᾧ νικήσετε τηνδὶ<br>ἐν τοῖσι λόγοις ἀντιλέγοντες, μαλακὸν δ᾽ ἐνδώσετε μηδέν."}, {"st": null, "sp": "Χορός", "t": "φανερὸν μὲν ἔγωγ᾽ οἶμαι γνῶναι τοῦτ᾽ εἶναι πᾶσιν ὁμοίως,<br>ὅτι τοὺς χρηστοὺς τῶν ἀνθρώπων εὖ πράττειν ἐστὶ δίκαιον,<br>τοὺς δὲ πονηροὺς καὶ τοὺς ἀθέους τούτων τἀναντία δήπου.<br>τοῦτ᾽ οὖν ἡμεῖς ἐπιθυμοῦντες μόλις ηὕρομεν, ὥστε γενέσθαι<br>βούλευμα καλὸν καὶ γενναῖον καὶ χρήσιμον εἰς ἅπαν ἔργον.<br>ἢν γὰρ ὁ Πλοῦτος νυνὶ βλέψῃ καὶ μὴ τυφλὸς ὢν περινοστῇ,<br>ὡς τοὺς ἀγαθοὺς τῶν ἀνθρώπων βαδιεῖται κοὐκ ἀπολείψει,<br>τοὺς δὲ πονηροὺς καὶ τοὺς ἀθέους φευξεῖται: κᾆτα ποιήσει<br>πάντας χρηστοὺς καὶ πλουτοῦντας δήπου τά τε θεῖα σέβοντας.<br>καίτοι τούτου τοῖς ἀνθρώποις τίς ἂν ἐξεύροι ποτ᾽ ἄμεινον;"}, {"st": null, "sp": "Βλεψίδημος", "t": "οὐδείς: τούτου μάρτυς ἐγώ σοι: μηδὲν ταύτην γ᾽ ἀνερώτα."}, {"st": "500", "sp": "Χρεμύλος", "t": "ὡς μὲν γὰρ νῦν ἡμῖν ὁ βίος τοῖς ἀνθρώποις διάκειται,<br>τίς ἂν οὐχ ἡγοῖτ᾽ εἶναι μανίαν κακοδαιμονίαν τ᾽ ἔτι μᾶλλον;<br>πολλοὶ μὲν γὰρ τῶν ἀνθρώπων ὄντες πλουτοῦσι πονηροί,<br>ἀδίκως αὐτὰ ξυλλεξάμενοι: πολλοὶ δ᾽ ὄντες πάνυ χρηστοὶ<br>πράττουσι κακῶς καὶ πεινῶσιν μετὰ σοῦ τε τὰ πλεῖστα σύνεισιν.<br>οὔκουν εἶναί φημ᾽, εἰ παύσει ταύτην βλέψας ποθ᾽ ὁ Πλοῦτος,<br>ὁδὸν ἥντιν᾽ ἰὼν τοῖς ἀνθρώποις ἀγάθ᾽ ἄν μείζω πορίσειεν."}, {"st": null, "sp": "Πενία", "t": "ἀλλ᾽ ὦ πάντων ῥᾷστ᾽ ἀνθρώπων ἀναπεισθέντ᾽ οὐχ ὑγιαίνειν<br>δύο πρεσβύτα, ξυνθιασώτα τοῦ ληρεῖν καὶ παραπαίειν,<br>εἰ τοῦτο γένοιθ᾽ ὃ ποθεῖθ᾽ ὑμεῖς, οὔ φημ᾽ ἂν λυσιτελεῖν σφῷν.<br>εἰ γὰρ ὁ Πλοῦτος βλέψειε πάλιν διανείμειέν τ᾽ ἴσον αὑτόν,<br>οὔτε τέχνην ἂν τῶν ἀνθρώπων οὔτ᾽ ἂν σοφίαν μελετῴη<br>οὐδείς: ἀμφοῖν δ᾽ ὑμῖν τούτοιν ἀφανισθέντοιν ἐθελήσει<br>τίς χαλκεύειν ἢ ναυπηγεῖν ἢ ῥάπτειν ἢ τροχοποιεῖν,<br>ἢ σκυτοτομεῖν ἢ πλινθουργεῖν ἢ πλύνειν ἢ σκυλοδεψεῖν,<br>ἢ γῆς ἀρότροις ῥήξας δάπεδον καρπὸν Δηοῦς θερίσασθαι,<br>ἢν ἐξῇ ζῆν ἀργοῖς ὑμῖν πάντων ἀμελοῦσιν;"}, {"st": null, "sp": "Χρεμύλος", "t": "λῆρον ληρεῖς. ταῦτα γὰρ ἡμῖν πάνθ᾽ ὅσα νῦν δὴ κατέλεξας<br>οἱ θεράποντες μοχθήσουσιν."}, {"st": null, "sp": "Πενία", "t": "πόθεν οὖν ἕξεις θεράποντας;"}, {"st": null, "sp": "Χρεμύλος", "t": "ὠνησόμεθ᾽ ἀργυρίου δήπου."}, {"st": null, "sp": "Πενία", "t": "τίς δ᾽ ἔσται πρῶτον ὁ πωλῶν,<br>ὅταν ἀργύριον κἀκεῖνος ἔχῃ;"}, {"st": null, "sp": "Χρεμύλος", "t": "κερδαίνειν βουλόμενός τις<br>ἔμπορος ἥκων ἐκ Θετταλίας παρὰ πλείστων ἀνδραποδιστῶν."}, {"st": null, "sp": "Πενία", "t": "ἀλλ᾽ οὐδ᾽ ἔσται πρῶτον ἁπάντων οὐδεὶς οὐδ᾽ ἀνδραποδιστὴς<br>κατὰ τὸν λόγον ὃν σὺ λέγεις δήπου. τίς γὰρ πλουτῶν ἐθελήσει<br>κινδυνεύων περὶ τῆς ψυχῆς τῆς αὑτοῦ τοῦτο ποιῆσαι;<br>ὥστ᾽ αὐτὸς ἀροῦν ἐπαναγκασθεὶς καὶ σκάπτειν τἄλλα τε μοχθεῖν<br>ὀδυνηρότερον τρίψεις βίοτον πολὺ τοῦ νῦν."}, {"st": null, "sp": "Χρεμύλος", "t": "ἐς κεφαλὴν σοί."}, {"st": null, "sp": "Πενία", "t": "ἔτι δ᾽ οὐχ ἕξεις οὔτ᾽ ἐν κλίνῃ καταδαρθεῖν, οὐ γὰρ ἔσονται,<br>οὔτ᾽ ἐν δάπισιν: τίς γὰρ ὑφαίνειν ἐθελήσει χρυσίου ὄντος;<br>οὔτε μύροισιν μυρίσαι στακτοῖς ὁπόταν νύμφην ἀγάγησθον.<br>οὔθ᾽ ἱματίων βαπτῶν δαπάναις κοσμῆσαι ποικιλομόρφων.<br>καίτοι τί πλέον πλουτεῖν ἐστιν τούτων πάντων ἀποροῦντας;<br>παρ᾽ ἐμοῦ δ᾽ ἔστιν ταῦτ᾽ εὔπορα πάνθ᾽ ὑμῖν ὧν δείσθον: ἐγὼ γὰρ<br>τὸν χειροτέχνην ὥσπερ δέσποιν᾽ ἐπαναγκάζουσα κάθημαι<br>διὰ τὴν χρείαν καὶ τὴν πενίαν ζητεῖν ὁπόθεν βίον ἕξει."}, {"st": "535", "sp": "Χρεμύλος", "t": "σὺ γὰρ ἂν πορίσαι τί δύναι᾽ ἀγαθὸν φῴδων ἐκ βαλανείου<br>καὶ παιδαρίων ὑποπεινώντων καὶ γραι:δίων κολοσυρτόν;<br>φθειρῶν τ᾽ ἀριθμὸν καὶ κωνώπων καὶ ψυλλῶν οὐδὲ λέγω σοι<br>ὑπὸ τοῦ πλήθους, αἳ βομβοῦσαι περὶ τὴν κεφαλὴν ἀνιῶσιν,<br>ἐπεγείρουσαι καὶ φράζουσαι, ‘πεινήσεις, ἀλλ᾽ ἐπανίστω.’<br>πρὸς δέ γε τούτοις ἀνθ᾽ ἱματίου μὲν ἔχειν ῥάκος: ἀντὶ δὲ κλίνης<br>στιβάδα σχοίνων κόρεων μεστήν, ἣ τοὺς εὕδοντας ἐγείρει:<br>καὶ φορμὸν ἔχειν ἀντὶ τάπητος σαπρόν: ἀντὶ δὲ προσκεφαλαίου<br>λίθον ἐυμεγέθη πρὸς τῇ κεφαλῇ: σιτεῖσθαι δ᾽ ἀντὶ μὲν ἄρτων<br>μαλάχης πτόρθους, ἀντὶ δὲ μάζης φυλλεῖ᾽ ἰσχνῶν ῥαφανίδων,<br>ἀντὶ δὲ θράνους στάμνου κεφαλὴν κατεαγότος, ἀντὶ δὲ μάκτρας<br>φιδάκνης πλευρὰν ἐρρωγυῖαν καὶ ταύτην. ἆρά γε πολλῶν<br>ἀγαθῶν πᾶσιν τοῖς ἀνθρὠποις ἀποφαίνω σ᾽ αἴτιον οὖσαν;"}, {"st": null, "sp": "Πενία", "t": "σὺ μὲν οὐ τὸν ἐμὸν βίον εἴρηκας, τὸν τῶν πτωχῶν δ᾽ ὑπεκρούσω."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐκοῦν δήπου τῆς Πτωχείας Πενίαν φαμὲν εἶναι ἀδελφήν."}, {"st": "550", "sp": "Πενία", "t": "ὑμεῖς γ᾽ οἵπερ καὶ Θρασυβούλῳ Διονύσιον εἶναι ὅμοιον.<br>ἀλλ᾽ οὐχ οὑμὸς τοῦτο πέπονθεν βίος οὐ μὰ Δί᾽, οὐδέ γε μέλλει.<br>πτωχοῦ μὲν γὰρ βίος, ὃν σὺ λέγεις, ζῆν ἐστιν μηδὲν ἔχοντα:<br>τοῦ δὲ πένητος ζῆν φειδόμενον καὶ τοῖς ἔργοις προς έχοντα,<br>περιγίγνεσθαι δ᾽ αὐτῷ μηδέν, μὴ μέντοι μηδ᾽ ἐπιλείπειν."}, {"st": "555", "sp": "Χρεμύλος", "t": "ὡς μακαρίτην ὦ Δάματερ τὸν βίον αὐτοῦ κατέλεξας,<br>εἰ φεισάμενος καὶ μοχθήσας καταλείψει μηδὲ ταφῆναι."}, {"st": null, "sp": "Πενία", "t": "σκώπτειν πειρᾷ καὶ κωμῳδεῖν τοῦ σπουδάζειν ἀμελήσας,<br>οὐ γιγνώσκων ὅτι τοῦ Πλούτου παρέχω βελτίονας ἄνδρας<br>καὶ τὴν γνώμην καὶ τὴν ἰδέαν. παρὰ τῷ μὲν γὰρ ποδαγρῶντες<br>καὶ γαστρώδεις καὶ παχύκνημοι καὶ πίονές εἰσιν ἀσελγῶς,<br>παρ᾽ ἐμοὶ δ᾽ ἰσχνοὶ καὶ σφηκώδεις καὶ τοῖς ἐχθροῖς ἀνιαροί."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀπὸ τοῦ λιμοῦ γὰρ ἴσως αὐτοῖς τὸ σφηκῶδες σὺ πορίζεις."}, {"st": null, "sp": "Πενία", "t": "περὶ σωφροσύνης ἤδη τοίνυν περανῶ σφῷν κἀναδιδάξω<br>ὅτι κοσμιότης οἰκεῖ μετ᾽ ἐμοῦ, τοῦ Πλούτου δ᾽ ἐστὶι ὑβρίζειν."}, {"st": "565", "sp": "Χρεμύλος", "t": "πάνυ γοῦν κλέπτειν κόσμιόν ἐστιν καὶ τοὺς τοίχους διορύττειν."}, {"st": null, "sp": "Βλεψίδημος", "t": "†νὴ τὸν Δί᾽, εἰ δεῖ λαθεῖν αὐτόν, πῶς οὐχὶ κόσμιόν ἐστι;†"}, {"st": null, "sp": "Πενία", "t": "σκέψαι τοίνυν ἐν ταῖς πόλεσιν τοὺς ῥήτορας, ὡς ὁπόταν μὲν<br>ὦσι πένητες, περὶ τὸν δῆμον καὶ τὴν πόλιν εἰσὶ δίκαιοι,<br>πλουτήσαντες δ᾽ ἀπὸ τῶν κοινῶν παραχρῆμ᾽ ἄδικοι γεγένηνται,<br>ἐπιβουλεύουσί τε τῷ πλήθει καὶ τῷ δήμῳ πολεμοῦσιν."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλ᾽ οὐ ψεύδει τούτων γ᾽ οὐδέν, καίπερ σφόδρα βάσκανος οὖσα.<br>ἀτὰρ οὐχ ἧττόν γ᾽ οὐδὲν κλαύσει, μηδὲν ταύτῃ γε κομήσῃς,<br>ὁτιὴ ζητεῖς τοῦτ᾽ ἀναπείθειν ἡμᾶς, ὡς ἔστιν ἄμεινον<br>Πενία Πλούτου."}, {"st": null, "sp": "Πενία", "t": "καὶ σύ γ᾽ ἐλέγξαι μ᾽ οὔπω δύνασαι περὶ τούτου,<br>ἀλλὰ φλυαρεῖς καὶ πτερυγίζεις."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ πῶς φεύγουσί σ᾽ ἅπαντες;"}, {"st": null, "sp": "Πενία", "t": "ὅτι βελτίους αὐτοὺς ποιῶ. σκέψασθαι δ᾽ ἔστι μάλιστα<br>ἀπὸ τῶν παίδων: τοὺς γὰρ πατέρας φεύγουσι φρονοῦντας ἄριστα<br>αὐτοῖς. οὕτω διαγιγνώσκειν χαλεπὸν πρᾶγμ᾽ ἐστὶ δίκαιον."}, {"st": null, "sp": "Χρεμύλος", "t": "τὸν Δία φήσεις ἆρ᾽ οὐκ ὀρθῶς διαγιγνώσκειν τὸ κράτιστον:<br>κἀκεῖνος γὰρ τὸν Πλοῦτον ἔχει."}, {"st": null, "sp": "Βλεψίδημος", "t": "ταύτην δ᾽ ἡμῖν ἀποπέμπει."}, {"st": null, "sp": "Πενία", "t": "ἀλλ᾽ ὦ Κρονικαῖς λήμαις ὄντως λημῶντες τὰς φρένας ἄμφω,<br>ὁ Ζεὺς δήπου πένεται, καὶ τοῦτ᾽ ἤδη φανερῶς σε διδάξω.<br>εἰ γὰρ ἐπλούτει, πῶς ἂν ποιῶν τὸν Ὀλυμπικὸν αὐτὸς ἀγῶνα<br>ἵνα τοὺς Ἕλληνας ἅπαντας ἀεὶ δι᾽ ἔτους πέμπτου ξυναγείρει,<br>ἀνεκήρυττεν τῶν ἀσκητῶν τοὺς νικῶντας στεφανώσας<br>κοτίνου στεφάνῳ; καίτοι χρυσῷ μᾶλλον ἐχρῆν, εἴπερ ἐπλούτει."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐκοῦν τούτῳ δήπου δηλοῖ τιμῶν τὸν Πλοῦτον ἐκεῖνος:<br>φειδόμενος γὰρ καὶ βουλόμενος τούτου μηδὲν δαπανᾶσθαι,<br>λήροις ἀναδῶν τοὺς νικῶντας τὸν Πλοῦτον ἐᾷ παρ᾽ ἑαυτῷ."}, {"st": "590", "sp": "Πενία", "t": "πολὺ τῆς Πενίας πρᾶγμ᾽ αἴσχιον ζητεῖς αὐτῷ περιάψαι,<br>εἰ πλούσιος ὢν ἀνελεύθερός ἐσθ᾽ οὑτωσὶ καὶ φιλοκερδής."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλὰ σέ γ᾽ ὁ Ζεὺς ἐξολέσειεν κοτίνου στεφάνῳ στεφανώσας."}, {"st": null, "sp": "Πενία", "t": "τὸ γὰρ ἀντιλέγειν τολμᾶν ὑμᾶς ὡς οὐ πάντ᾽ ἔστ᾽ ἀγάθ᾽ ὑμῖν<br>διὰ τὴν Πενίαν."}, {"st": null, "sp": "Χρεμύλος", "t": "παρὰ τῆς Ἑκάτης ἔξεστιν τοῦτο πυθέσθαι,<br>εἴτε τὸ πλουτεῖν εἴτε τὸ πεινῆν βέλτιον. φησὶ γὰρ αὕτη<br>τοὺς μὲν ἔχοντας καὶ πλουτοῦντας δεῖπνον κατὰ μῆν᾽ ἀποπέμπειν,<br>τοὺς δὲ πένητας τῶν ἀνθρώπων ἁρπάζειν πρὶν καταθεῖναι."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλὰ φθείρου καὶ μὴ γρύξῃς<br>ἔτι μηδ᾽ ὁτιοῦν.<br>οὐ γὰρ πείσεις, οὐδ᾽ ἢν πείσῃς."}, {"st": null, "sp": "Πενία", "t": "ὦ πόλις Ἄργους, κλύεθ᾽ οἷα λέγει."}, {"st": null, "sp": "Χρεμύλος", "t": "Παύσωνα κάλει τὸν ξύσσιτον."}, {"st": null, "sp": "Πενία", "t": "τί πάθω τλήμων;"}, {"st": null, "sp": "Χρεμύλος", "t": "ἔρρ᾽ ἐς κόρακας θᾶττον ἀφ᾽ ἡμῶν."}, {"st": "605", "sp": "Πενία", "t": "εἶμι δὲ ποῖ γῆς;"}, {"st": null, "sp": "Χρεμύλος", "t": "ἐς τὸν κύφων᾽: ἀλλ᾽ οὐ μέλλειν<br>χρῆν σ᾽, ἀλλ᾽ ἀνύειν."}, {"st": null, "sp": "Πενία", "t": "ἦ μὴν ὑμεῖς γ᾽ ἔτι μ᾽ ἐνταυθοῖ<br>μεταπέμψεσθον."}, {"st": "610", "sp": "Χρεμύλος", "t": "τότε νοστήσεις: νῦν δὲ φθείρου.<br>κρεῖττον γάρ μοι πλουτεῖν ἐστίν,<br>σὲ δ᾽ ἐᾶν κλάειν μακρὰ τὴν κεφαλήν."}, {"st": null, "sp": "Βλεψίδημος", "t": "νὴ Δί᾽ ἐγὼ γοῦν ἐθέλω πλουτῶν<br>εὐωχεῖσθαι μετὰ τῶν παίδων<br>τῆς τε γυναικός, καὶ λουσάμενος<br>λιπαρὸς χωρῶν ἐκ βαλανείου<br>τῶν χειροτεχνῶν<br>καὶ τῆς Πενίας καταπαρδεῖν."}, {"st": null, "sp": "Χρεμύλος", "t": "αὕτη μὲν ἡμῖν ἡπίτριπτος οἴχεται.<br>ἐγὼ δὲ καὶ σύ γ᾽ ὡς τάχιστα τὸν θεὸν<br>ἐγκατακλινοῦντ᾽ ἄγωμεν εἰς Ἀσκληπιοῦ."}, {"st": null, "sp": "Βλεψίδημος", "t": "καὶ μὴ διατρίβωμέν γε, μὴ πάλιν τις αὖ<br>ἐλθὼν διακωλύσῃ τι τῶν προὔργου ποιεῖν."}, {"st": null, "sp": "Χρεμύλος", "t": "παῖ Καρίων τὰ στρώματ᾽ ἐκφέρειν σ᾽ ἐχρῆν<br>αὐτόν τ᾽ ἄγειν τὸν Πλοῦτον, ὡς νομίζεται,<br>καὶ τἄλλ᾽ ὅσ᾽ ἐστὶν ἔνδον ηὐτρεπισμένα."}, {"st": null, "sp": "N", "t": "ὦ πλεῖστα Θησείοις μεμυστιλημένοι γέροντες ἄνδρες ἐπ᾽ ὀλιγίστοις ἀλφίτοις,<br>ὡς εὐτυχεῖθ᾽, ὡς μακαρίως πεπράγατε,<br>ἄλλοι θ᾽ ὅσοις μέτεστι τοῦ χρηστοῦ τρόπου."}, {"st": null, "sp": "Χορός", "t": "τί δ᾽ ἔστιν ὦ βέλτιστε τῶν σαυτοῦ φίλων;<br>φαίνει γὰρ ἥκειν ἄγγελος χρηστοῦ τινος."}, {"st": null, "sp": "Καρίων", "t": "ὁ δεσπότης πέπραγεν εὐτυχέστατα,<br>μᾶλλον δ᾽ ὁ Πλοῦτος αὐτός: ἀντὶ γὰρ τυφλοῦ<br>ἐξωμμάτωται καὶ λελάμπρυνται κόρας,<br>Ἀσκληπιοῦ παιῶνος εὐμενοῦς τυχών."}, {"st": null, "sp": "Χορός", "t": "λέγεις μοι χαράν, λέγεις μοι βοάν."}, {"st": null, "sp": "Καρίων", "t": "πάρεστι χαίρειν, ἤν τε βούλησθ᾽ ἤν τε μή."}, {"st": null, "sp": "N", "t": "ἀναβοάσομαι τὸν εὔπαιδα καὶ μέγα βροτοῖσι φέγγος Ἀσκληπιόν."}, {"st": null, "sp": "Γυνή", "t": "τίς ἡ βοή ποτ᾽ ἐστίν; ἆρ᾽ ἀγγέλλεται<br>χρηστόν τι; τοῦτο γὰρ ποθοῦσ᾽ ἐγὼ πάλαι<br>ἔνδον κάθημαι περιμένουσα τουτονί."}, {"st": null, "sp": "Καρίων", "t": "ταχέως ταχέως φέρ᾽ οἶνον ὦ δέσποιν᾽, ἵνα<br>καὐτὴ πίῃς: φιλεῖς δὲ δρῶσ᾽ αὐτὸ σφόδρα:<br>ὡς ἀγαθὰ συλλήβδην ἅπαντά σοι φέρω."}, {"st": null, "sp": "Γυνή", "t": "καὶ ποῦ στιν;"}, {"st": null, "sp": "Καρίων", "t": "ἐν τοῖς λεγομένοις εἴσει τάχα."}, {"st": null, "sp": "Γυνή", "t": "πέραινε τοίνυν ὅ τι λέγεις ἀνύσας ποτέ."}, {"st": null, "sp": "Καρίων", "t": "ἄκουε τοίνυν, ὡς ἐγὼ τὰ πράγματα<br>ἐκ τῶν ποδῶν ἐς τὴν κεφαλήν σοι πάντ᾽ ἐρῶ."}, {"st": null, "sp": "Γυνή", "t": "μὴ δῆτ᾽ ἔμοιγ᾽ ἐς τὴν κεφαλήν."}, {"st": null, "sp": "Καρίων", "t": "μὴ τἀγαθὰ<br>ἃ νῦν γεγένηται;"}, {"st": null, "sp": "Γυνή", "t": "μὴ μὲν οὖν τὰ πράγματα."}, {"st": null, "sp": "Καρίων", "t": "ὡς γὰρ τάχιστ᾽ ἀφικόμεθα πρὸς τὸν θεὸν<br>ἄγοντες ἄνδρα τότε μὲν ἀθλιώτατον<br>νῦν δ᾽ εἴ τιν᾽ ἄλλον μακάριον κεὐδαίμονα,<br>πρῶτον μὲν αὐτὸν ἐπὶ θάλατταν ἤγομεν,<br>ἔπειτ᾽ ἐλοῦμεν."}, {"st": null, "sp": "Γυνή", "t": "νὴ Δί᾽ εὐδαίμων ἄρ᾽ ἦν<br>ἀνὴρ γέρων ψυχρᾷ θαλάττῃ λούμενος."}, {"st": null, "sp": "Καρίων", "t": "ἔπειτα πρὸς τὸ τέμενος ᾖμεν τοῦ θεοῦ.<br>ἐπεὶ δὲ βωμῷ πόπανα καὶ προθύματα<br>καθωσιώθη πέλανος Ἡφαίστου φλογί,<br>κατεκλίναμεν τὸν Πλοῦτον, ὥσπερ εἰκὸς ἦν:<br>ἡμῶν δ᾽ ἕκαστος στιβάδα παρεκαττύετο."}, {"st": null, "sp": "Γυνή", "t": "ἦσαν δέ τινες κἄλλοι δεόμενοι τοῦ θεοῦ;"}, {"st": "665", "sp": "Καρίων", "t": "εἷς μέν γε Νεοκλείδης, ὅς ἐστι μὲν τυφλός,<br>κλέπτων δὲ τοὺς βλέποντας ὑπερηκόντικεν:<br>ἕτεροί τε πολλοὶ παντοδαπὰ νοσήματα<br>ἔχοντες: ὡς δὲ τοὺς λύχνους ἀποσβέσας<br>ἡμῖν παρήγγειλεν καθεύδειν τοῦ θεοῦ<br>ὁ πρόπολος, εἰπών, ἤν τις αἴσθηται ψόφου<br>σιγᾶν, ἅπαντες κοσμίως κατεκείμεθα.<br>κἀγὼ καθεύδειν οὐκ ἐδυνάμην, ἀλλά με<br>ἀθάρης χύτρα τις ἐξέπληττε κειμένη<br>ὀλίγον ἄπωθεν τῆς κεφαλῆς του γρᾳδίου,<br>ἐφ᾽ ἣν ἐπεθύμουν δαιμονίως ἐφερπύσαι.<br>ἔπειτ᾽ ἀναβλέψας ὁρῶ τὸν ἱερέα<br>τοὺς φθοῖς ἀφαρπάζοντα καὶ τὰς ἰσχάδας<br>ἀπὸ τῆς τραπέζης τῆς ἱερᾶς: μετὰ τοῦτο δὲ<br>περιῆλθε τοὺς βωμοὺς ἅπαντας ἐν κύκλῳ,<br>εἴ που πόπανον εἴη τι καταλελειμμένον:<br>ἔπειτα ταῦθ᾽ ἥγιζεν ἐς σάκταν τινά.<br>κἀγὼ νομίσας πολλὴν ὁσίαν τοῦ πράγματος<br>ἐπὶ τὴν χύτραν τῆς ἀθάρης ἀνίσταμαι."}, {"st": null, "sp": "Γυνή", "t": "ταλάντατ᾽ ἀνδρῶν οὐκ ἐδεδοίκεις τὸν θεόν;"}, {"st": "685", "sp": "Καρίων", "t": "νὴ τοὺς θεοὺς ἔγωγε μὴ φθάσειέ με<br>ἐπὶ τὴν χύτραν ἐλθὼν ἔχων τὰ στέμματα:<br>ὁ γὰρ ἱερεὺς αὐτοῦ με προὐδιδάξατο.<br>τὸ γρᾴδιον δ᾽ ὡς ᾔσθετο δή μου τὸν ψόφον,<br>ἄρασ᾽ ὑφῄρει: κᾆτα συρίξας ἐγὼ<br>ὀδὰξ ἐλαβόμην ὡς παρείας ὢν ὄφις.<br>ἡ δ᾽ εὐθέως τὴν χεῖρα πάλιν ἀνέσπασεν,<br>κατέκειτο δ᾽ αὑτὴν ἐντυλίξασ᾽ ἡσυχῇ<br>ὑπὸ τοῦ δέους βδέουσα δριμύτερον γαλῆς.<br>κἀγὼ τότ᾽ ἤδη τῆς ἀθάρης πολλὴν ἔφλων:<br>ἔπειτ᾽ ἐπειδὴ μεστὸς ἦν, ἀνεπαλλόμην."}, {"st": null, "sp": "Γυνή", "t": "ὁ δὲ θεὸς ὑμῖν οὐ προσῄειν;"}, {"st": null, "sp": "Καρίων", "t": "οὐδέπω.<br>μετὰ τοῦτο δ᾽ ἤδη καὶ γέλοιον δῆτά τι<br>ἐποίησα. προσιόντος γὰρ αὐτοῦ μέγα πάνυ<br>ἀπέπαρδον: ἡ γαστὴρ γὰρ ἐπεφύσητό μου."}, {"st": "700", "sp": "Γυνή", "t": "ἦ πού σε διὰ τοῦτ᾽ εὐθὺς ἐβδελύττετο."}, {"st": null, "sp": "Καρίων", "t": "οὔκ, ἀλλ᾽ Ἰασὼ μέν τις ἀκολουθοῦσ᾽ ἅμα<br>ὑπηρυθρίασε χἠ Πανάκει᾽ ἀπεστράφη<br>τὴν ῥῖν᾽ ἐπιλαβοῦσ᾽: οὐ λιβανωτὸν γὰρ βδέω."}, {"st": null, "sp": "Γυνή", "t": "αὐτὸς δ᾽ ἐκεῖνος;"}, {"st": null, "sp": "Καρίων", "t": "οὐ μὰ Δί᾽ οὐδ᾽ ἐφρόντισεν."}, {"st": "705", "sp": "Γυνή", "t": "λέγεις ἄγροικον ἄρα σύ γ᾽ εἶναι τὸν θεόν."}, {"st": null, "sp": "Καρίων", "t": "μὰ Δί᾽ οὐκ ἔγωγ᾽, ἀλλὰ σκατοφάγον."}, {"st": null, "sp": "Γυνή", "t": "αἲ τάλαν."}, {"st": null, "sp": "Καρίων", "t": "μετὰ ταῦτ᾽ ἐγὼ μὲν εὐθὺς ἐνεκαλυψάμην<br>δείσας, ἐκεῖνος δ᾽ ἐν κύκλῳ τὰ νοσήματα<br>σκοπῶν περιῄει πάντα κοσμίως πάνυ.<br>ἔπειτα παῖς αὐτῷ λίθινον θυείδιον<br>παρέθηκε καὶ δοίδυκα καὶ κιβώτιον."}, {"st": null, "sp": "Γυνή", "t": "λίθινον;"}, {"st": null, "sp": "Καρίων", "t": "μὰ Δί᾽ οὐ δῆτ᾽ οὐχὶ τό γε κιβώτιον."}, {"st": null, "sp": "Γυνή", "t": "σὺ δὲ πῶς ἑώρας ὦ κάκιστ᾽ ἀπολούμενε,<br>ὃς ἐγκεκαλύφθαι φῄς;"}, {"st": null, "sp": "Καρίων", "t": "διὰ τοῦ τριβωνίου:<br>ὀπὰς γὰρ εἶχεν οὐκ ὀλίγας μὰ τὸν Δία.<br>πρῶτον δὲ πάντων τῷ Νεοκλείδῃ φάρμακον<br>καταπλαστὸν ἐνεχείρησε τρίβειν, ἐμβαλὼν<br>σκορόδων κεφαλὰς τρεῖς Τηνίων. ἔπειτ᾽ ἔφλα<br>ἐν τῇ θυείᾳ συμπαραμιγνύων ὀπὸν<br>καὶ σχῖνον: εἶτ᾽ ὄξει διέμενος Σφηττίῳ<br>κατέπλασεν αὐτοῦ τὰ βλέφαρ᾽ ἐκστρέψας, ἵνα<br>ὀδυνῷτο μᾶλλον. ὁ δὲ κεκραγὼς καὶ βοῶν<br>ἔφευγ᾽ ἀνᾴξας: ὁ δὲ θεὸς γελάσας ἔφη:<br>‘ἐνταῦθα νῦν κάθησο καταπεπλασμένος,<br>ἵν᾽ ὑπομνύμενον παύσω σε τὰς ἐκκλησίας.’"}, {"st": null, "sp": "Γυνή", "t": "ὡς φιλόπολίς τίς ἐσθ᾽ ὁ δαίμων καὶ σοφός."}, {"st": null, "sp": "Καρίων", "t": "μετὰ τοῦτο τῷ Πλούτωνι παρεκαθέζετο,<br>καὶ πρῶτα μὲν δὴ τῆς κεφαλῆς ἐφήψατο,<br>ἔπειτα καθαρὸν ἡμιτύβιον λαβὼν<br>τὰ βλέφαρα περιέψησεν: ἡ Πανάκεια δὲ<br>κατεπέτασ᾽ αὐτοῦ τὴν κεφαλὴν φοινικίδι<br>καὶ πᾶν τὸ πρόσωπον: εἶθ᾽ ὁ θεὸς ἐπόππυσεν.<br>ἐξῃξάτην οὖν δύο δράκοντ᾽ ἐκ τοῦ νεὼ<br>ὑπερφυεῖς τὸ μέγεθος."}, {"st": null, "sp": "Γυνή", "t": "ὦ φίλοι θεοί."}, {"st": "735", "sp": "Καρίων", "t": "τούτω δ᾽ ὑπὸ τὴν φοινικίδ᾽ ὑποδύνθ᾽ ἡσυχῇ<br>τὰ βλέφαρα περιέλειχον, ὥς γ᾽ ἐμοὶ δοκεῖ:<br>καὶ πρίν σε κοτύλας ἐκπιεῖν οἴνου δέκα,<br>ὁ Πλοῦτος ὦ δέσποιν᾽ ἀνειστήκει βλέπων:<br>ἐγὼ δὲ τὼ χεῖρ᾽ ἀνεκρότησ᾽ ὑφ᾽ ἡδονῆς<br>τὸν δεσπότην τ᾽ ἤγειρον. ὁ θεὸς δ᾽ εὐθέως<br>ἠφάνισεν αὑτὸν οἵ τ᾽ ὄφεις ἐς τὸν νεών.<br>οἱ δ᾽ ἐγκατακείμενοι παρ᾽ αὐτῷ πῶς δοκεῖς<br>τὸν Πλοῦτον ἠσπάζοντο καὶ τὴν νύχθ᾽ ὅλην<br>ἐγρηγόρεσαν, ἕως διέλαμψεν ἡμέρα.<br>ἐγὼ δ᾽ ἐπῄνουν τὸν θεὸν πάνυ σφόδρα,<br>ὅτι βλέπειν ἐποίησε τὸν Πλοῦτον ταχύ,<br>τὸν δὲ Νεοκλείδην μᾶλλον ἐποίησεν τυφλόν."}, {"st": null, "sp": "Γυνή", "t": "ὅσην ἔχεις τὴν δύναμιν ὦναξ δέσποτα.<br>ἀτὰρ φράσον μοι, ποῦ᾽ σθ᾽ ὁ Πλοῦτος;"}, {"st": null, "sp": "Καρίων", "t": "ἔρχεται.<br>ἀλλ᾽ ἦν περὶ αὐτὸν ὄχλος ὑπερφυὴς ὅσος.<br>οἱ γὰρ δίκαιοι πρότερον ὄντες καὶ βίον<br>ἔχοντες ὀλίγον αὐτὸν ἠσπάζοντο καὶ<br>ἐδεξιοῦνθ᾽ ἅπαντες ὑπὸ τῆς ἡδονῆς:<br>ὅσοι δ᾽ ἐπλούτουν οὐσίαν τ᾽ εἶχον συχνὴν<br>οὐκ ἐκ δικαίου τὸν βίον κεκτημένοι,<br>ὀφρῦς ξυνῆγον ἐσκυθρώπαζόν θ᾽ ἅμα.<br>οἱ δ᾽ ἠκολούθουν κατόπιν ἐστεφανωμένοι<br>γελῶντες εὐφημοῦντες: ἐκτυπεῖτο δὲ<br>ἐμβὰς γερόντων εὐρύθμοις προβήμασιν.<br>ἀλλ᾽ εἶ᾽ ἁπαξάπαντες ἐξ ἑνὸς λόγου<br>ὀρχεῖσθε καὶ σκιρτᾶτε καὶ χορεύετε:<br>οὐδεὶς γὰρ ὑμῖν εἰσιοῦσιν ἀγγελεῖ,<br>ὡς ἄλφιτ᾽ οὐκ ἔνεστιν ἐν τῷ θυλάκῳ."}, {"st": null, "sp": "Γυνή", "t": "νὴ τὴν Ἑκάτην κἀγὼ δ᾽ ἀναδῆσαι βούλομαι<br>εὐαγγέλιά σε κριβανωτῶν ὁρμαθῷ<br>τοιαῦτ᾽ ἀπαγγείλαντα."}, {"st": null, "sp": "Καρίων", "t": "μή νυν μέλλ᾽ ἔτι,<br>ὡς ἅνδρες ἐγγύς εἰσιν ἤδη τῶν θυρῶν."}, {"st": null, "sp": "Γυνή", "t": "φέρε νυν ἰοῦσ᾽ εἴσω κομίσω καταχύσματα<br>ὥσπερ νεωνήτοισιν ὀφθαλμοῖς ἐγώ."}, {"st": "770", "sp": "Καρίων", "t": "ἐγὼ δ᾽ ἀπαντῆσαί γ᾽ ἐκείνοις βούλομαι."}, {"st": null, "sp": "Πλοῦτος", "t": "καὶ προσκυνῶ γε πρῶτα μὲν τὸν ἥλιον,<br>ἔπειτα σεμνῆς Παλλάδος κλεινὸν πέδον<br>χώραν τε πᾶσαν Κέκροπος ἥ μ᾽ ἐδέξατο.<br>αἰσχύνομαι δὲ τὰς ἐμαυτοῦ συμφοράς,<br>οἵοις ἄρ᾽ ἀνθρώποις ξυνὼν ἐλάνθανον,<br>τοὺς ἀξίους δὲ τῆς ἐμῆς ὁμιλίας<br>ἔφευγον, εἰδὼς οὐδέν: ὦ τλήμων ἐγώ,<br>ὡς οὔτ᾽ ἐκεῖν᾽ ἄρ᾽ οὔτε ταῦτ᾽ ὀρθῶς ἔδρων:<br>ἀλλ᾽ αὐτὰ πάντα πάλιν ἀναστρέψας ἐγὼ<br>δείξω τὸ λοιπὸν πᾶσιν ἀνθρώποις ὅτι<br>ἄκων ἐμαυτὸν τοῖς πονηροῖς ἐπεδίδουν."}, {"st": null, "sp": "Χρεμύλος", "t": "βάλλ᾽ ἐς κόρακας: ὡς χαλεπόν εἰσιν οἱ φίλοι<br>οἱ φαινόμενοι παραχρῆμ᾽ ὅταν πράττῃ τις εὖ.<br>νύττουσι γὰρ καὶ φλῶσι τἀντικνήμια,<br>ἐνδεικνύμενος ἔκαστος εὔνοιάν τινα.<br>ἐμὲ γὰρ τίς οὐ προσεῖπε; ποῖος οὐκ ὄχλος<br>περιεστεφάνωσεν ἐν ἀγορᾷ πρεσβυτικός;"}, {"st": null, "sp": "Γυνή", "t": "ὦ φίλτατ᾽ ἀνδρῶν καὶ σὺ καὶ σὺ χαίρετε.<br>φέρε νυν, νόμος γάρ ἐστι, τὰ καταχύσματα<br>ταυτὶ καταχέω σου λαβοῦσα."}, {"st": null, "sp": "Πλοῦτος", "t": "μηδαμῶς.<br>ἐμοῦ γὰρ εἰσιόντος ἐς τὴν οἰκίαν<br>πρώτιστα καὶ βλέψαντος οὐδὲν ἐκφέρειν<br>πρεπῶδές ἐστιν, ἀλλὰ μᾶλλον ἐσφέρειν."}, {"st": null, "sp": "Γυνή", "t": "εἶτ᾽ οὐχὶ δέξει δῆτα τὰ καταχύσματα;"}, {"st": "795", "sp": "Πλοῦτος", "t": "ἔνδον γε παρὰ τὴν ἑστίαν, ὥσπερ νόμος:<br>ἔπειτα καὶ τὸν φόρτον ἐκφύγοιμεν ἄν.<br>οὐ γὰρ πρεπῶδές ἐστι τῷ διδασκάλῳ<br>ἰσχάδια καὶ τρωγάλια τοῖς θεωμένοις<br>προβαλόντ᾽ ἐπὶ τούτοις εἶτ᾽ ἀναγκάζειν γελᾶν."}, {"st": "800", "sp": "Γυνή", "t": "εὖ πάνυ λέγεις: ὡς Δεξίνικός γ᾽ οὑτοσὶ<br>ἀνίσταθ᾽ ὡς ἁρπασόμενος τὰς ἰσχάδας."}, {"st": null, "sp": "Καρίων", "t": "ὡς ἡδὺ πράττειν ὦνδρές ἐστ᾽ εὐδαιμόνως,<br>καὶ ταῦτα μηδὲν ἐξενεγκόντ᾽ οἴκοθεν.<br>ἡμῖν γὰρ ἀγαθῶν σωρὸς ἐς τὴν οἰκίαν<br>ἐπεσπέπαικεν οὐδὲν ἠδικηκόσιν.<br>οὕτω τὸ πλουτεῖν ἐστιν ἡδὺ πρᾶγμα δή.<br>ἡ μὲν σιπύη μεστή ‘στι λευκῶν ἀλφίτων,<br>οἱ δ᾽ ἀμφορῆς οἴνου μέλανος ἀνθοσμίου.<br>ἅπαντα δ᾽ ἡμῖν ἀργυρίου καὶ χρυσίου<br>τὰ σκευάρια πλήρη ‘στίν, ὥστε θαυμάσαι.<br>τὸ φρέαρ δ᾽ ἐλαίου μεστόν: αἱ δὲ λήκυθοι<br>μύρου γέμουσι, τὸ δ᾽ ὑπερῷον ἰσχάδων.<br>ὀξὶς δὲ πᾶσα καὶ λοπάδιον καὶ χύτρα<br>χαλκῆ γέγονε: τοὺς δὲ πινακίσκους τοὺς σαπροὺς<br>τοὺς ἰχθυηροὺς ἀργυροῦς πάρεσθ᾽ ὁρᾶν.<br>ὁ δ᾽ ἰπνὸς γέγον᾽ ἡμῖν ἐξαπίνης ἐλεφάντινος.<br>στατῆρσι δ᾽ οἱ θεράποντες ἀρτιάζομεν<br>χρυσοῖς: ἀποψώμεσθα δ᾽ οὐ λίθοις ἔτι,<br>ἀλλὰ σκοροδίοις ὑπὸ τρυφῆς ἑκάστοτε.<br>καὶ νῦν ὁ δεσπότης μὲν ἔνδον βουθυτεῖ<br>ὗν καὶ τράγον καὶ κριὸν ἐστεφανωμένος:<br>ἐμὲ δ᾽ ἐξέπεμψεν ὁ καπνός. οὐχ οἷός τε γὰρ<br>ἔνδον μένειν ἦν. ἔδακνε γὰρ τὰ βλέφαρά μου."}, {"st": null, "sp": "Δίκαιος", "t": "ἕπου μετ᾽ ἐμοῦ παιδάριον, ἵνα πρὸς τὸν θεὸν<br>ἴωμεν."}, {"st": null, "sp": "Καρίων", "t": "ἔα τίς ἔσθ᾽ ὁ προσιὼν οὑτοσί;"}, {"st": "825", "sp": "Δίκαιος", "t": "ἀνὴρ πρότερον μὲν ἄθλιος, νῦν δ᾽ εὐτυχής."}, {"st": null, "sp": "Καρίων", "t": "δῆλον ὅτι τῶν χρηστῶν τις, ὡς ἔοικας, εἶ."}, {"st": null, "sp": "Δίκαιος", "t": "μάλιστ᾽."}, {"st": null, "sp": "Καρίων", "t": "ἔπειτα τοῦ δέει;"}, {"st": null, "sp": "Δίκαιος", "t": "πρὸς τὸν θεὸν<br>ἥκω: μεγάλων γάρ μοὐστὶν ἀγαθῶν αἴτιος.<br>ἐγὼ γὰρ ἱκανὴν οὐσίαν παρὰ τοῦ πατρὸς<br>λαβὼν ἐπήρκουν τοῖς δεομένοις τῶν φίλων,<br>εἶναι νομίζων χρήσιμον πρὸς τὸν βίον."}, {"st": null, "sp": "Καρίων", "t": "ἦ πού σε ταχέως ἐπέλιπεν τὰ χρήματα."}, {"st": null, "sp": "Δίκαιος", "t": "κομιδῇ μὲν οὖν."}, {"st": null, "sp": "Καρίων", "t": "οὐκοῦν μετὰ ταῦτ᾽ ἦσθ᾽ ἄθλιος."}, {"st": null, "sp": "Δίκαιος", "t": "κομιδῇ μὲν οὖν. κἀγὼ μὲν ᾤμην οὓς τέως<br>εὐηργέτησα δεομένους ἕξειν φίλους<br>ὄντως βεβαίους, εἰ δεηθείην ποτέ:<br>οἱ δ᾽ ἐξετρέποντο κοὐκ ἐδόκουν ὁρᾶν μ᾽ ἔτι."}, {"st": null, "sp": "Καρίων", "t": "καὶ κατεγέλων δ᾽ εὖ οἶδ᾽ ὅτι."}, {"st": null, "sp": "Δίκαιος", "t": "κομιδῇ μὲν οὖν:<br>αὐχμὸς γὰρ ὢν τῶν σκευαρίων μ᾽ ἀπώλεσεν."}, {"st": "840", "sp": "Καρίων", "t": "ἀλλ᾽ οὐχὶ νῦν."}, {"st": null, "sp": "Δίκαιος", "t": "ἀνθ᾽ ὧν ἐγὼ πρὸς τὸν θεὸν<br>προσευξόμενος ἥκω δικαίως ἐνθάδε."}, {"st": null, "sp": "Καρίων", "t": "τὸ τριβώνιον δὲ τί δύναται πρὸς τῶν θεῶν,<br>ὃ φέρει μετὰ σοῦ τὸ παιδάριον τουτί; φράσον."}, {"st": null, "sp": "Δίκαιος", "t": "καὶ τοῦτ᾽ ἀναθήσων ἔρχομαι πρὸς τὸν θεόν."}, {"st": "845", "sp": "Καρίων", "t": "μῶν οὖν ἐμυήθης δῆτ᾽ ἐν αὐτῷ τὰ μεγάλα;"}, {"st": null, "sp": "Δίκαιος", "t": "οὐκ ἀλλ᾽ ἐνερρίγωσ᾽ ἔτη τριακαίδεκα."}, {"st": null, "sp": "Καρίων", "t": "τὰ δ᾽ ἐμβάδια;"}, {"st": null, "sp": "Δίκαιος", "t": "καὶ ταῦτα συνεχειμάζετο."}, {"st": null, "sp": "Καρίων", "t": "καὶ ταῦτ᾽ ἀναθήσων ἔφερες οὖν;"}, {"st": null, "sp": "Δίκαιος", "t": "νὴ τὸν Δία."}, {"st": null, "sp": "Καρίων", "t": "χαρίεντά γ᾽ ἥκεις δῶρα τῷ θεῷ φέρων."}, {"st": "850", "sp": "Συκοφάντης", "t": "οἴμοι κακοδαίμων, ὡς ἀπόλωλα δείλαιος,<br>καὶ κακοδαίμων καὶ τετράκις καὶ πεντάκις<br>καὶ δωδεκάκις καὶ μυριάκις: ἰοὺ ἰού.<br>οὕτω πολυφόρῳ συγκέκραμαι δαίμονι."}, {"st": null, "sp": "Καρίων", "t": "Ἄπολλον ἀποτρόπαιε καὶ θεοὶ φίλοι,<br>τί ποτ᾽ ἐστὶν ὅ τι πέπονθεν ἅνθρωπος κακόν;"}, {"st": null, "sp": "Συκοφάντης", "t": "οὐ γὰρ σχέτλια πέπονθα νυνὶ πράγματα,<br>ἀπολωλεκὼς ἅπαντα τἀκ τῆς οἰκίας<br>διὰ τὸν θεὸν τοῦτον, τὸν ἐσόμενον τυφλὸν<br>πάλιν αὖθις, ἤνπερ μὴ ‘λλίπωσιν αἱ δίκαι;"}, {"st": "860", "sp": "Δίκαιος", "t": "ἐγὼ σχεδὸν τὸ πρᾶγμα γιγνώσκειν δοκῶ.<br>προσέρχεται γάρ τις κακῶς πράττων ἀνήρ,<br>ἔοικε δ᾽ εἶναι τοῦ πονηροῦ κόμματος."}, {"st": null, "sp": "Καρίων", "t": "νὴ Δία καλῶς τοίνυν ποιῶν ἀπόλλυται."}, {"st": null, "sp": "Συκοφάντης", "t": "ποῦ ποῦ ‘σθ᾽ ὁ μόνος ἅπαντας ἡμᾶς πλουσίους<br>ὑποσχόμενος οὗτος ποιήσειν εὐθέως,<br>εἰ πάλιν ἀναβλέψειεν ἐξ ἀρχῆς; ὁ δὲ<br>πολὺ μᾶλλον ἐνίους ἐστὶν ἐξολωλεκώς."}, {"st": null, "sp": "Καρίων", "t": "καὶ τίνα δέδρακε δῆτα τοῦτ᾽;"}, {"st": null, "sp": "Συκοφάντης", "t": "ἐμὲ τουτονί."}, {"st": null, "sp": "Καρίων", "t": "ἦ τῶν πονηρῶν ἦσθα καὶ τοιχωρύχων;"}, {"st": "870", "sp": "Συκοφάντης", "t": "μὰ Δί᾽ οὐ μὲν οὖν ἔσθ᾽ ὑγιὲς ὑμῶν οὐδενός,<br>κοὐκ ἔσθ᾽ ὅπως οὐκ ἔχετέ μου τὰ χρήματα."}, {"st": null, "sp": "Καρίων", "t": "ὡς σοβαρὸς ὦ Δάματερ εἰσελήλυθεν<br>ὁ συκοφάντης. δῆλον ὅτι βουλιμιᾷ."}, {"st": null, "sp": "Συκοφάντης", "t": "σὺ μὲν εἰς ἀγορὰν ἰὼν ταχέως οὐκ ἂν φθάνοις:<br>ἐπὶ τοῦ τροχοῦ γὰρ δεῖ σ᾽ ἐκεῖ στρεβλούμενον<br>εἰπεῖν ἃ πεπανούργηκας."}, {"st": null, "sp": "Καρίων", "t": "οἰμώξἄρα σύ."}, {"st": null, "sp": "Δίκαιος", "t": "νὴ τὸν Δία τὸν σωτῆρα πολλοῦ γ᾽ ἄξιος<br>ἅπασι τοῖς Ἕλλησιν ὁ θεός ἐσθ᾽ ὅτι<br>τοὺς συκοφάντας ἐξολεῖ κακοὺς κακῶς."}, {"st": "880", "sp": "Συκοφάντης", "t": "οἴμοι τάλας: μῶν καὶ σὺ μετέχων καταγελᾷς;<br>ἐπεὶ πόθεν θοἰμάτιον εἴληφας τοδί;<br>ἐχθὲς δ᾽ ἔχοντ᾽ εἶδόν σ᾽ ἐγὼ τριβώνιον."}, {"st": null, "sp": "Δίκαιος", "t": "οὐδὲν προτιμῶ σου. φορῶ γὰρ πριάμενος<br>τὸν δακτύλιον τονδὶ παρ᾽ Εὐδάμου δραχμῆς."}, {"st": "885", "sp": "Καρίων", "t": "† ἀλλ᾽ οὐκ ἔνεστι συκοφάντου δήγματος.†"}, {"st": null, "sp": "Συκοφάντης", "t": "ἆρ᾽ οὐχ ὕβρις ταῦτ᾽ ἐστὶ πολλή; σκώπτετον,<br>ὅ τι δὲ ποιεῖτον ἐνθάδ᾽ οὐκ εἰρήκατον.<br>οὐκ ἐπ᾽ ἀγαθῷ γὰρ ἐνθάδ᾽ ἐστὸν οὐδενί."}, {"st": null, "sp": "Δίκαιος", "t": "μὰ τὸν Δί᾽ οὔκουν τῷ γε σῷ, σάφ᾽ ἴσθ᾽ ὅτι."}, {"st": "890", "sp": "Συκοφάντης", "t": "ἀπὸ τῶν ἐμῶν γὰρ ναὶ μὰ Δία δειπνήσετον."}, {"st": null, "sp": "Καρίων", "t": "ὡς δὴ ‘π᾽ ἀληθείᾳ σὺ μετὰ τοῦ μάρτυρος<br>διαρραγείης μηδενός γ᾽ ἐμπλήμενος."}, {"st": null, "sp": "Συκοφάντης", "t": "ἀρνεῖσθον; ἔνδον ἐστὶν ὦ μιαρωτάτω<br>πολὺ χρῆμα τεμαχῶν καὶ κρεῶν ὠπτημένων.<br>ὓ ὗ ὓ ὗ ὓ ὗ ὓ ὗ ὓ ὗ ὓ ὗ."}, {"st": null, "sp": "Καρίων", "t": "κακόδαιμον ὀσφραίνει τι;"}, {"st": null, "sp": "Δίκαιος", "t": "τοῦ ψύχους γ᾽ ἴσως<br>ἐπεὶ τοιοῦτόν γ᾽ ἀμπέχεται τριβώνιον."}, {"st": null, "sp": "Συκοφάντης", "t": "ταῦτ᾽ οὖν ἀνασχέτ᾽ ἐστὶν ὦ Ζεῦ καὶ θεοί,<br>τούτους ὑβρίζειν εἰς ἔμ᾽; οἴμ᾽ ὡς ἄχθομαι<br>ὅτι χρηστὸς ὢν καὶ φιλόπολις πάσχω κακῶς."}, {"st": null, "sp": "Δίκαιος", "t": "σὺ φιλόπολις καὶ χρηστός;"}, {"st": null, "sp": "Συκοφάντης", "t": "ὡς οὐδείς γ᾽ ἀνήρ."}, {"st": null, "sp": "Δίκαιος", "t": "καὶ μὴν ἐπερωτηθεὶς ἀπόκριναί μοι."}, {"st": null, "sp": "Συκοφάντης", "t": "τὸ τί;"}, {"st": null, "sp": "Δίκαιος", "t": "γεωργὸς εἶ;"}, {"st": null, "sp": "Συκοφάντης", "t": "μελαγχολᾶν μ᾽ οὕτως οἴει;"}, {"st": null, "sp": "Δίκαιος", "t": "ἀλλ᾽ ἔμπορος;"}, {"st": null, "sp": "Συκοφάντης", "t": "ναί, σκήπτομαί γ᾽, ὅταν τύχω."}, {"st": "905", "sp": "Δίκαιος", "t": "τί δαί; τέχνην τιν᾽ ἔμαθες;"}, {"st": null, "sp": "Συκοφάντης", "t": "οὐ μὰ τὸν Δία."}, {"st": null, "sp": "Δίκαιος", "t": "πῶς οὖν διέζης ἢ πόθεν μηδὲν ποιῶν;"}, {"st": null, "sp": "Συκοφάντης", "t": "τῶν τῆς πόλεώς εἰμ᾽ ἐπιμελητὴς πραγμάτων<br>καὶ τῶν ἰδίων πάντων."}, {"st": null, "sp": "Δίκαιος", "t": "σύ; τί μαθών;"}, {"st": null, "sp": "Συκοφάντης", "t": "βούλομαι."}, {"st": null, "sp": "Δίκαιος", "t": "πῶς οὖν ἂν εἴης χρηστὸς ὦ τοιχωρύχε,<br>εἴ σοι προσῆκον μηδὲν εἶτ᾽ ἀπεχθάνει;"}, {"st": null, "sp": "Συκοφάντης", "t": "οὐ γὰρ προσήκει τὴν ἐμαυτοῦ μοι πόλιν<br>εὐεργετεῖν ὦ κέπφε καθ᾽ ὅσον ἂν σθένω;"}, {"st": null, "sp": "Δίκαιος", "t": "εὐεργετεῖν οὖν ἐστι τὸ πολυπραγμονεῖν;"}, {"st": null, "sp": "Συκοφάντης", "t": "τὸ μὲν οὖν βοηθεῖν τοῖς νόμοις τοῖς κειμένοις<br>καὶ μὴ ‘πιτρέπειν ἐάν τις ἐξαμαρτάνῃ."}, {"st": null, "sp": "Δίκαιος", "t": "οὔκουν δικαστὰς ἐξεπίτηδες ἡ πόλις<br>ἄρχειν καθίστησιν;"}, {"st": null, "sp": "Συκοφάντης", "t": "κατηγορεῖ δὲ τίς;"}, {"st": null, "sp": "Δίκαιος", "t": "ὁ βουλόμενος."}, {"st": null, "sp": "Συκοφάντης", "t": "οὐκοῦν ἐκεῖνός εἰμ᾽ ἐγώ,<br>ὥστ᾽ εἰς ἔμ᾽ ἥκει τῆς πόλεως τὰ πράγματα."}, {"st": "920", "sp": "Δίκαιος", "t": "νὴ Δία πονηρόν γ᾽ ἆρα προστάτην ἔχει.<br>ἐκεῖνο δ᾽ οὐ βούλοι᾽ ἄν, ἡσυχίαν ἔχων<br>ζῆν ἀργός;"}, {"st": null, "sp": "Συκοφάντης", "t": "ἀλλὰ προβατίου βίον λέγεις,<br>εἰ μὴ φανεῖται διατριβή τις τῷ βίῳ."}, {"st": null, "sp": "Δίκαιος", "t": "οὐδ᾽ ἂν μεταμάθοις;"}, {"st": null, "sp": "Συκοφάντης", "t": "οὐδ᾽ ἂν εἰ δοίης γέ μοι<br>τὸν Πλοῦτον αὐτὸν καὶ τὸ Βάττου σίλφιον."}, {"st": null, "sp": "Δίκαιος", "t": "κατάθου ταχέως θοἰμάτιον."}, {"st": null, "sp": "Καρίων", "t": "οὗτος, σοὶ λέγει."}, {"st": null, "sp": "Δίκαιος", "t": "ἔπειθ᾽ ὑπόλυσαι."}, {"st": null, "sp": "Καρίων", "t": "ταῦτα πάντα σοὶ λέγει."}, {"st": null, "sp": "Συκοφάντης", "t": "καὶ μὴν προσελθέτω πρὸς ἔμ᾽ ὑμῶν ἐνθαδὶ<br>ὁ βουλόμενος."}, {"st": null, "sp": "Καρίων", "t": "οὐκοῦν ἐκεῖνός εἰμ᾽ ἐγώ."}, {"st": "930", "sp": "Συκοφάντης", "t": "οἴμοι τάλας ἀποδύομαι μεθ᾽ ἡμέραν."}, {"st": null, "sp": "Καρίων", "t": "σὺ γὰρ ἀξιοῖς τἀλλότρια πράττων ἐσθίειν."}, {"st": null, "sp": "Συκοφάντης", "t": "ὁρᾷς ἃ ποιεῖς; ταῦτ᾽ ἐγὼ μαρτύρομαι."}, {"st": null, "sp": "Δίκαιος", "t": "ἀλλ᾽ οἴχεται φεύγων ὃν ἦγες μάρτυρα."}, {"st": null, "sp": "Συκοφάντης", "t": "οἴμοι περιείλημμαι μόνος."}, {"st": null, "sp": "Καρίων", "t": "νυνὶ βοᾷς;"}, {"st": "935", "sp": "Συκοφάντης", "t": "οἴμοι μάλ᾽ αὖθις."}, {"st": null, "sp": "Καρίων", "t": "δὸς σύ μοι τὸ τριβώνιον,<br>ἵν᾽ ἀμφιέσω τὸν συκοφάντην τουτονί."}, {"st": null, "sp": "Δίκαιος", "t": "μὴ δῆθ᾽: ἱερὸν γάρ ἐστι τοῦ Πλούτου πάλαι."}, {"st": null, "sp": "N", "t": "ἔπειτα ποῦ κάλλιον ἀνατεθήσεται ἢ περὶ πονηρὸν ἄνδρα καὶ τοιχωρύχον;<br>Πλοῦτον δὲ κοσμεῖν ἱματίοις σεμνοῖς πρέπει."}, {"st": null, "sp": "Δίκαιος", "t": "τοῖς δ᾽ ἐμβαδίοις τί χρήσεταί τις; εἰπέ μοι."}, {"st": null, "sp": "Καρίων", "t": "καὶ ταῦτα πρὸς τὸ μέτωπον αὐτίκα δὴ μάλα<br>ὥσπερ κοτίνῳ προσπατταλεύσω τουτῳί."}, {"st": null, "sp": "Συκοφάντης", "t": "ἄπειμι: γιγνώσκω γὰρ ἥττων ὢν πολὺ<br>ὑμῶν: ἐὰν δὲ σύζυγον λάβω τινὰ<br>καὶ σύκινον, τοῦτον τὸν ἰσχυρὸν θεὸν<br>ἐγὼ ποιήσω τήμερον δοῦναι δίκην,<br>ὁτιὴ καταλύει περιφανῶς εἶς ὢν μόνος<br>τὴν δημοκρατίαν, οὔτε τὴν βουλὴν πιθὼν<br>τὴν τῶν πολιτῶν οὔτε τὴν ἐκκλησίαν."}, {"st": null, "sp": "Δίκαιος", "t": "καὶ μὴν ἐπειδὴ τὴν πανοπλίαν τὴν ἐμὴν<br>ἔχων βαδίζεις, ἐς τὸ βαλανεῖον τρέχε:<br>ἔπειτ᾽ ἐκεῖ κορυφαῖος ἑστηκὼς θέρου.<br>κἀγὼ γὰρ εἶχον τὴν στάσιν ταύτην ποτέ."}, {"st": "955", "sp": "Καρίων", "t": "ἀλλ᾽ ὁ βαλανεὺς ἕλξει θύραζ᾽ αὐτὸν λαβὼν<br>τῶν ὀρχιπέδων: ἰδὼν γὰρ αὐτὸν γνώσεται<br>ὅτι ἔστ᾽ ἐκείνου τοῦ πονηροῦ κόμματος.<br>νὼ δ᾽ εἰσίωμεν, ἵνα προσεύξῃ τὸν θεόν."}, {"st": null, "sp": "Γραῦς", "t": "ἆρ᾽ ὦ φίλοι γέροντες ἐπὶ τὴν οἰκίαν<br>ἀφίγμεθ᾽ ὄντως τοῦ νέου τούτου θεοῦ,<br>ἢ τῆς ὁδοῦ τὸ παράπαν ἡμαρτήκαμεν;"}, {"st": null, "sp": "Χορός", "t": "ἀλλ᾽ ἴσθ᾽ ἐπ᾽ αὐτὰς τὰς θύρας ἀφιγμένη<br>ὦ μειρακίσκη: πυνθάνει γὰρ ὡρικῶς."}, {"st": null, "sp": "Γραῦς", "t": "φέρε νυν ἐγὼ τῶν ἔνδοθεν καλέσω τινά."}, {"st": "965", "sp": "Χρεμύλος", "t": "μὴ δῆτ᾽: ἐγὼ γὰρ αὐτὸς ἐξελήλυθα.<br>ἀλλ᾽ ὅ τι μάλιστ᾽ ἐλήλυθας λέγειν σ᾽ ἐχρῆν."}, {"st": null, "sp": "Γραῦς", "t": "πέπονθα δεινὰ καὶ παράνομ᾽ ὦ φίλτατε:<br>ἀφ᾽ οὗ γὰρ ὁ θεὸς οὗτος ἤρξατο βλέπειν,<br>ἀβίωτον εἶναί μοι πεποίηκε τὸν βίον."}, {"st": "970", "sp": "Χρεμύλος", "t": "τί δ᾽ ἔστιν; ἦ που καὶ σὺ συκοφάντρια<br>εν ταῖς γυναιξὶν ἦσθα;"}, {"st": null, "sp": "Γραῦς", "t": "μὰ Δί᾽ ἐγὼ μὲν οὔ."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλ᾽ οὐ λαχοῦσ᾽ ἔπινες ἐν τῷ γράμματι;"}, {"st": null, "sp": "Γραῦς", "t": "σκώπτεις: ἐγὼ δὲ κατακέκνισμαι δειλάκρα."}, {"st": null, "sp": "Χρεμύλος", "t": "οὔκουν ἐρεῖς ἀνύσασα τὸν κνισμὸν τίνα;"}, {"st": "975", "sp": "Γραῦς", "t": "ἄκουέ νυν. ἦν μοί τι μειράκιον φίλον,<br>πενιχρὸν μέν, ἄλλως δ᾽ εὐπρόσωπον καὶ καλὸν<br>καὶ χρηστόν: εἰ γάρ του δεηθείην ἐγώ,<br>ἅπαντ᾽ ἐποίει κοσμίως μοι καὶ καλῶς:<br>ἐγὼ δ᾽ ἐκείνῳ πάντα ταῦθ᾽ ὑπηρέτουν."}, {"st": "980", "sp": "Χρεμύλος", "t": "τί δ᾽ ἦν ὅ τι σου μάλιστ᾽ ἐδεῖθ᾽ ἑκάστοτε;"}, {"st": null, "sp": "Γραῦς", "t": "οὐ πολλά: καὶ γὰρ ἐκνομίως μ᾽ ᾐσχύνετο.<br>ἀλλ᾽ ἀργυρίου δραχμὰς ἂν ᾔτησ᾽ εἴκοσιν<br>εἰς ἱμάτιον, ὀκτὼ δ᾽ ἂν εἰς ὑποδήματα:<br>καὶ ταῖς ἀδελφαῖς ἀγοράσαι χιτώνιον<br>ἐκέλευσεν ἂν τῇ μητρί θ᾽ ἱματίδιον:<br>πυρῶν τ᾽ ἂν ἐδεήθη μεδίμνων τεττάρων."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐ πολλὰ τοίνυν μὰ τὸν Ἀπόλλω ταῦτά γε<br>εἴρηκας, ἀλλὰ δῆλον ὅτι σ᾽ ᾐσχύνετο."}, {"st": null, "sp": "Γραῦς", "t": "καὶ ταῦτα τοίνυν οὐχ ἕνεκα μισητίας<br>αἰτεῖν μ᾽ ἔφασκεν, ἀλλὰ φιλίας οὕνεκα,<br>ἵνα τοὐμὸν ἱμάτιον φορῶν μεμνῇτό μου."}, {"st": null, "sp": "Χρεμύλος", "t": "λέγεις ἐρῶντ᾽ ἄνθρωπον ἐκνομιώτατα."}, {"st": null, "sp": "Γραῦς", "t": "ἀλλ᾽ οὐχὶ νῦν ὁ βδελυρὸς ἔτι τὸν νοῦν ἔχει<br>τὸν αὐτόν, ἀλλὰ πολὺ μεθέστηκεν πάνυ.<br>ἐμοῦ γὰρ αὐτῷ τὸν πλακοῦντα τουτονὶ<br>καὶ τἄλλα τἀπὶ τοῦ πίνακος τραγήματα<br>ἐπόντα πεμψάσης ὑπειπούσης θ᾽ ὅτι<br>εἰς ἑσπέραν ἥξοιμι —"}, {"st": null, "sp": "Χρεμύλος", "t": "τί σ᾽ ἔδρασ᾽; εἰπέ μοι."}, {"st": null, "sp": "Γραῦς", "t": "ἄμητα προσαπέπεμψεν ἡμῖν τουτονί,<br>ἐφ᾽ ᾧ τ᾽ ἐκεῖσε μηδέποτέ μ᾽ ἐλθεῖν ἔτι,<br>καὶ πρὸς ἐπὶ τούτοις εἶπεν ἀποπέμπων ὅτι<br>‘ πάλαι ποτ᾽ ἦσαν ἄλκιμοι Μιλήσιοι.’"}, {"st": null, "sp": "Χρεμύλος", "t": "δῆλον ὅτι τοὺς τρόπους τις οὐ μοχθηρὸς ἦν,<br>ἔπειτα πλουτῶν οὐκέθ᾽ ἥδεται φακῇ:<br>πρὸ τοῦ δ᾽ ὑπὸ τῆς πενίας ἅπανθ᾽ ὑπήσθιεν."}, {"st": null, "sp": "Γραῦς", "t": "καὶ μὴν πρὸ τοῦ γ᾽ ὁσημέραι νὴ τὼ θεὼ<br>ἐπὶ τὴν θύραν ἐβάδιζεν ἀεὶ τὴν ἐμήν."}, {"st": null, "sp": "Χρεμύλος", "t": "ἐπ᾽ ἐκφοράν;"}, {"st": null, "sp": "Γραῦς", "t": "μὰ Δί᾽ ἀλλὰ τῆς φωνῆς μόνον<br>ἐρῶν ἀκοῦσαι."}, {"st": null, "sp": "Χρεμύλος", "t": "τοῦ λαβεῖν μὲν οὖν χάριν."}, {"st": "1010", "sp": "Γραῦς", "t": "καὶ νὴ Δί᾽ εἰ λυπουμένην γ᾽ αἴσθοιτό με,<br>νηττάριον ἂν καὶ φάττιον ὑπεκορίζετο."}, {"st": null, "sp": "Χρεμύλος", "t": "ἔπειτ᾽ ἴσως ᾔτει σ᾽ ἂν εἰς ὑποδήματα."}, {"st": null, "sp": "Γραῦς", "t": "μυστηρίοις δὲ τοῖς μεγάλοις ὀχουμένην<br>ἐπὶ τῆς ἁμάξης ὅτι προσέβλεψέν μέ τις,<br>ἐτυπτόμην διὰ τοῦθ᾽ ὅλην τὴν ἡμέραν.<br>οὕτω σφόδρα ζηλότυπος ὁ νεανίσκος ἦν."}, {"st": null, "sp": "Χρεμύλος", "t": "μόνος γὰρ ἥδεθ᾽, ὡς ἔοικεν, ἐσθίων."}, {"st": null, "sp": "Γραῦς", "t": "καὶ τάς γε χεῖρας παγκάλας ἔχειν μ᾽ ἔθη."}, {"st": null, "sp": "Χρεμύλος", "t": "ὁπότε προτείνοιέν γε δραχμὰς εἴκοσιν."}, {"st": "1020", "sp": "Γραῦς", "t": "ὄζειν τε τῆς χρόας ἔφασκεν ἡδύ μου."}, {"st": null, "sp": "Χρεμύλος", "t": "εἰ Θάσιον ἐνέχεις, εἰκότως γε νὴ Δία."}, {"st": null, "sp": "Γραῦς", "t": "τὸ βλέμμα θ᾽ ὡς ἔχοιμι μαλακὸν καὶ καλόν."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐ σκαιὸς ἦν ἄνθρωπος, ἀλλ᾽ ἠπίστατο<br>γραὸς καπρώσης τἀφόδια κατεσθίειν."}, {"st": "1025", "sp": "Γραῦς", "t": "ταῦτ᾽ οὖν ὁ θεὸς ὦ φίλ᾽ ἄνερ οὐκ ὀρθῶς ποιεῖ,<br>φάσκων βοηθεῖν τοῖς ἀδικουμένοις ἀεί."}, {"st": null, "sp": "Χρεμύλος", "t": "τί γὰρ ποιήσει; φράζε, καὶ πεπράξεται."}, {"st": null, "sp": "Γραῦς", "t": "ἀναγκάσαι δίκαιόν ἐστι νὴ Δία<br>τὸν εὖ παθόνθ᾽ ὑπ᾽ ἐμοῦ πάλιν μ᾽ ἀντευποιεῖν,<br>ἢ μηδ᾽ ὁτιοῦν ἀγαθὸν δίκαιόν ἐστ᾽ ἔχειν."}, {"st": null, "sp": "Χρεμύλος", "t": "οὔκουν καθ᾽ ἑκάστην ἀπεδίδου τὴν νύκτα σοι;"}, {"st": null, "sp": "Γραῦς", "t": "ἀλλ᾽ οὐδέποτέ με ζῶσαν ἀπολείψειν ἔφη."}, {"st": null, "sp": "Χρεμύλος", "t": "ὀρθῶς γε: νῦν δέ γ᾽ οὐκέτι ζῆν σ᾽ οἴεται."}, {"st": null, "sp": "Γραῦς", "t": "ὑπὸ τοῦ γὰρ ἄλγους κατατέτηκ᾽ ὦ φίλτατε."}, {"st": "1035", "sp": "Χρεμύλος", "t": "οὐκ ἀλλὰ κατασέσηπας, ὥς γ᾽ ἐμοὶ δοκεῖς."}, {"st": null, "sp": "Γραῦς", "t": "διὰ δακτυλίου μὲν οὖν ἔμεγ᾽ ἂν διελκύσαις."}, {"st": null, "sp": "Χρεμύλος", "t": "εἰ τυγχάνοι γ᾽ ὁ δακτύλιος ὢν τηλία."}, {"st": null, "sp": "Γραῦς", "t": "καὶ μὴν τὸ μειράκιον τοδὶ προσέρχεται,<br>οὗπερ πάλαι κατηγοροῦσα τυγχάνω:<br>ἔοικε δ᾽ ἐπὶ κῶμον βαδίζειν."}, {"st": null, "sp": "Χρεμύλος", "t": "φαίνεται.<br>στέφανόν γέ τοι καὶ δᾷδ᾽ ἔχων πορεύεται."}, {"st": null, "sp": "Νεανίας", "t": "ἀσπάζομαί σε."}, {"st": null, "sp": "Γραῦς", "t": "τί φησιν;"}, {"st": null, "sp": "Νεανίας", "t": "ἀρχαία φίλη,<br>πολιὰ γεγένησαι ταχύ γε νὴ τὸν οὐρανόν."}, {"st": null, "sp": "Γραῦς", "t": "τάλαιν᾽ ἐγὼ τῆς ὕβρεος ἧς ὑβρίζομαι."}, {"st": "1045", "sp": "Χρεμύλος", "t": "ἔοικε διὰ πολλοῦ χρόνου σ᾽ ἑορακέναι."}, {"st": null, "sp": "Γραῦς", "t": "ποίου χρόνου ταλάνταθ᾽, ὃς παρ᾽ ἐμοὶ χθὲς ἦν;"}, {"st": null, "sp": "Χρεμύλος", "t": "τοὐναντίον πέπονθε τοῖς πολλοῖς ἄρα:<br>μεθύων γάρ, ὡς ἔικεν, ὀξύτερον βλέπει."}, {"st": null, "sp": "Γραῦς", "t": "οὔκ, ἀλλ᾽ ἀκόλαστός ἐστιν ἀεὶ τοὺς τρόπους."}, {"st": "1050", "sp": "Νεανίας", "t": "ὦ Ποντοπόσειδον καὶ θεοὶ πρεσβυτικοί,<br>ἐν τῷ προσώπῳ τῶν ῥυτίδων ὅσας ἔχει."}, {"st": null, "sp": "Γραῦς", "t": "ἆ ἆ,<br>τὴν δᾷδα μή μοι πρόσφερ᾽."}, {"st": null, "sp": "Χρεμύλος", "t": "εὖ μέντοι λέγει.<br>ἐὰν γὰρ αὐτὴν εἷς μόνος σπινθὴρ λάβῃ<br>ὥσπερ παλαιὰν εἰρεσιώνην καύσεται."}, {"st": "1055", "sp": "Νεανίας", "t": "βούλει διὰ χρόνου πρός με παῖσαι;"}, {"st": null, "sp": "Γραῦς", "t": "ποῖ τάλαν;"}, {"st": null, "sp": "Νεανίας", "t": "αὐτοῦ, λαβοῦσα κάρυα."}, {"st": null, "sp": "Γραῦς", "t": "παιδιὰν τίνα;"}, {"st": null, "sp": "Νεανίας", "t": "πόσους ἔχεις ὀδόντας."}, {"st": null, "sp": "Χρεμύλος", "t": "ἀλλὰ γνώσομαι<br>κἄγωγ᾽: ἔχει γὰρ τρεῖς ἴσως ἢ τέτταρας."}, {"st": null, "sp": "Νεανίας", "t": "ἀπότεισον: ἕνα γὰρ γόμφιον μόνον φορεῖ."}, {"st": "1060", "sp": "Γραῦς", "t": "ταλάντατ᾽ ἀνδρῶν οὐχ ὑγιαίνειν μοι δοκεῖς,<br>πλυνόν με ποιῶν ἐν τοσούτοις ἀνδράσιν."}, {"st": null, "sp": "Νεανίας", "t": "ὄναιο μέντἄν, εἴ τις ἐκπλύνειέ σε."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐ δῆτ᾽, ἐπεὶ νῦν μὲν καπηλικῶς ἔχει,<br>εἰ δ᾽ ἐκπλυνεῖται τοῦτο τὸ ψιμύθιον,<br>ὄψει κατάδηλα τοῦ προσώπου τὰ ῥάκη."}, {"st": null, "sp": "Γραῦς", "t": "γέρων ἀνὴρ ὢν οὐχ ὑγιαίνειν μοι δοκεῖς."}, {"st": null, "sp": "Νεανίας", "t": "πειρᾷ μὲν οὖν ἴσως σε καὶ τῶν τιτθίων<br>ἐφάπτεταί σου λανθάνειν δοκῶν ἐμέ."}, {"st": null, "sp": "Γραῦς", "t": "μὰ τὴν Ἀφροδίτην οὐκ ἐμοῦ γ᾽ ὦ βδελυρὲ σύ."}, {"st": "1070", "sp": "Χρεμύλος", "t": "μὰ τὴν Ἑκάτην οὐ δῆτα: μαινοίμην γὰρ ἄν.<br>ἀλλ᾽ ὦ νεανίσκ᾽ οὐκ ἐῶ τὴν μείρακα<br>μισεῖν σε ταύτην."}, {"st": null, "sp": "Νεανίας", "t": "ἀλλ᾽ ἔγωγ᾽ ὑπερφιλῶ."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ μὴν κατηγορεῖ γέ σου."}, {"st": null, "sp": "Νεανίας", "t": "τί κατηγορεῖ;"}, {"st": null, "sp": "Χρεμύλος", "t": "εἶναί σ᾽ ὑβριστήν φησι καὶ λέγειν ὅτι<br>‘ πάλαι ποτ᾽ ἦσαν ἄλκιμοι Μιλήσιοι.’"}, {"st": null, "sp": "Νεανίας", "t": "ἐγὼ περὶ ταύτης οὐ μαχοῦμαί σοι."}, {"st": null, "sp": "Χρεμύλος", "t": "τὸ τί;"}, {"st": null, "sp": "Νεανίας", "t": "αἰσχυνόμενος τὴν ἡλικίαν τὴν σήν, ἐπεὶ<br>οὐκ ἄν ποτ᾽ ἄλλῳ τοῦτ᾽ ἐπέτρεψ᾽ ἐγὼ ποιεῖν:<br>νῦν δ᾽ ἄπιθι χαίρων συλλαβὼν τὴν μείρακα."}, {"st": "1080", "sp": "Χρεμύλος", "t": "οἶδ᾽ οἶδα τὸν νοῦν: οὐκέτ᾽ ἀξιοῖς ἴσως<br>εἶναι μετ᾽ αὐτῆς."}, {"st": null, "sp": "Γραῦς", "t": "ὁ δ᾽ ἐπιτρέψων ἐστὶ τίς;"}, {"st": null, "sp": "N", "t": "οὐκ ἂν διαλεχθείην διεσπλεκωμένῃ ὑπὸ μυρίων ἐτῶν γε καὶ τρισχιλίων."}, {"st": null, "sp": "Χρεμύλος", "t": "ὅμως δ᾽ ἐπειδὴ καὶ τὸν οἶνον ἠξίους<br>πίνειν, συνεκποτέ᾽ ἐστί σοι καὶ τὴν τρύγα."}, {"st": null, "sp": "Νεανίας", "t": "ἀλλ᾽ ἔστι κομιδῇ τρὺξ παλαιὰ καὶ σαπρά."}, {"st": null, "sp": "Χρεμύλος", "t": "οὐκοῦν τρύγοιπος ταῦτα πάντ᾽ ἰάσεται."}, {"st": null, "sp": "Νεανίας", "t": "ἀλλ᾽ εἴσιθ᾽ εἴσω: τῷ θεῷ γὰρ βούλομαι<br>ἐλθὼν ἀναθεῖναι τοὺς στεφάνους τούσδ᾽ οὓς ἔχω."}, {"st": "1090", "sp": "Γραῦς", "t": "ἐγὼ δέ γ᾽ αὐτῷ καὶ φράσαι τι βούλομαι."}, {"st": null, "sp": "Νεανίας", "t": "ἐγὼ δέ γ᾽ οὐκ εἴσειμι."}, {"st": null, "sp": "Χρεμύλος", "t": "θάρρει, μὴ φοβοῦ.<br>οὐ γὰρ βιάσεται."}, {"st": null, "sp": "Νεανίας", "t": "πάνυ καλῶς τοίνυν λέγεις.<br>ἱκανὸν γὰρ αὐτὴν πρότερον ὑπεπίττουν χρόνον."}, {"st": null, "sp": "Γραῦς", "t": "βάδιζ᾽: ἐγὼ δέ σου κατόπιν εἰσέρχομαι."}, {"st": "1095", "sp": "Χρεμύλος", "t": "ὡς εὐτόνως ὦ Ζεῦ βασιλεῦ τὸ γρᾴδιον<br>ὥσπερ λεπὰς τῷ μειρακίῳ προσείχετο."}, {"st": null, "sp": "Καρίων", "t": "τίς ἔσθ᾽ ὁ κόπτων τὴν θύραν; τουτὶ τί ἦν;<br>οὐδεὶς ἔοικεν: ἀλλὰ δῆτα τὸ θύριον<br>φθεγγόμενον ἄλλως κλαυσιᾷ."}, {"st": null, "sp": "Ἑρμῆς", "t": "σέ τοι λέγω,<br>ὁ Καρίων, ἀνάμεινον."}, {"st": null, "sp": "Καρίων", "t": "οὗτος εἰπέ μοι,<br>σὺ τὴν θύραν ἔκοπτες οὑτωσὶ σφόδρα;"}, {"st": null, "sp": "Ἑρμῆς", "t": "μὰ Δί᾽ ἀλλ᾽ ἔμελλον: εἶτ᾽ ἀνέῳξάς με φθάσας.<br>ἀλλ᾽ ἐκκάλει τὸν δεσπότην τρέχων ταχύ,<br>ἒπειτα τὴν γυναῖκα καὶ τὰ παιδία,<br>ἔπειτα τοὺς θεράποντας, εἶτα τὴν κύνα,<br>ἔπειτα σαυτόν, εἶτα τὴν ὗν."}, {"st": null, "sp": "Καρίων", "t": "εἰπέ μοι,<br>τί δ᾽ ἔστιν;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ὁ Ζεὺς ὦ πόνηρε βούλεται<br>ἐς ταὐτὸν ὑμᾶς συγκυκήσας τρύβλιον<br>ἁπαξάπαντας ἐς τὸ βάραθρον ἐμβαλεῖν."}, {"st": "1110", "sp": "Καρίων", "t": "ἡ γλῶττα τῷ κήρυκι τούτων τέμνεται.<br>ἀτὰρ διὰ τί δὴ ταῦτ᾽ ἐπιβουλεύει ποιεῖν<br>ἡμᾶς;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ὁτιὴ δεινότατα πάντων πραγμάτων<br>εἴργασθ᾽. ἀφ᾽ οὗ γὰρ ἤρξατ᾽ ἐξ ἀρχῆς βλέπειν<br>ὁ Πλοῦτος, οὐδεὶς οὐ λιβανωτόν, οὐ δάφνην,<br>οὐ ψαιστόν, οὐχ ἱερεῖον, οὐκ ἄλλ᾽ οὐδὲ ἓν<br>ἡμῖν ἔτι θύει τοῖς θεοῖς."}, {"st": null, "sp": "Καρίων", "t": "μὰ Δί᾽ οὐδέ γε<br>θύσει. κακῶς γὰρ ἐπεμελεῖσθ᾽ ἡμῶν τότε."}, {"st": null, "sp": "Ἑρμῆς", "t": "καὶ τῶν μὲν ἄλλων μοι θεῶν ἧττον μέλει,<br>ἐγὼ δ᾽ ἀπόλωλα κἀπιτέτριμμαι."}, {"st": null, "sp": "Καρίων", "t": "σωφρονεῖς."}, {"st": "1120", "sp": "Ἑρμῆς", "t": "πρότερον γὰρ εἶχον μὲν παρὰ ταῖς καπηλίσιν<br>πάντ᾽ ἀγάθ᾽ ἕωθεν εὐθύς, οἰνοῦτταν μέλι<br>ἰσχάδας, ὅσ᾽ εἰκός ἐστιν Ἑρμῆν ἐσθίειν:<br>νυνὶ δὲ πεινῶν ἀναβάδην ἀναπαύομαι."}, {"st": null, "sp": "Καρίων", "t": "οὔκουν δικαίως, ὅστις ἐποίεις ζημίαν<br>ἐνίοτε τοιαῦτ᾽ ἀγάθ᾽ ἔχων;"}, {"st": null, "sp": "Ἑρμῆς", "t": "οἴμοι τάλας,<br>οἴμοι πλακοῦντος τοῦ ν᾽ τετράδι πεπεμμένου."}, {"st": null, "sp": "Καρίων", "t": "ποθεῖς τὸν οὐ παρόντα καὶ μάτην καλεῖς."}, {"st": null, "sp": "Ἑρμῆς", "t": "οἴμοι δὲ κωλῆς ἣν ἐγὼ κατήσθιον."}, {"st": null, "sp": "Καρίων", "t": "ἀσκωλίαζ᾽ ἐνταῦθα πρὸς τὴν αἰθρίαν."}, {"st": "1130", "sp": "Ἑρμῆς", "t": "σπλάγχνων τε θερμῶν ὧν ἐγὼ κατήσθιον."}, {"st": null, "sp": "Καρίων", "t": "ὀδύνη σε περὶ τὰ σπλάγχν᾽ ἔοικέ τι στρέφειν."}, {"st": null, "sp": "Ἑρμῆς", "t": "οἴμοι δὲ κύλικος ἴσον ἴσῳ κεκραμένης."}, {"st": null, "sp": "Καρίων", "t": "ταύτην ἐπιπιὼν ἀποτρέχων οὐκ ἂν φθάνοις."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἆρ᾽ ὠφελήσαις ἄν τι τὸν σαυτοῦ φίλον;"}, {"st": "1135", "sp": "Καρίων", "t": "εἴ του δέει γ᾽ ὧν δυνατός εἰμί σ᾽ ὠφελεῖν."}, {"st": null, "sp": "Ἑρμῆς", "t": "εἴ μοι πορίσας ἄρτον τιν᾽ εὖ πεπεμμένον<br>δοίης καταφαγεῖν καὶ κρέας νεανικὸν<br>ὧν θύεθ᾽ ὑμεῖς ἔνδον."}, {"st": null, "sp": "Καρίων", "t": "ἀλλ᾽ οὐκ ἐκφορά."}, {"st": null, "sp": "Ἑρμῆς", "t": "καὶ μὴν ὁπότε τι σκευάριον τοῦ δεσπότου<br>ὑφέλοι᾽, ἐγώ σε λανθάνειν ἐποίουν ἀεί."}, {"st": null, "sp": "Καρίων", "t": "ἐφ᾽ ᾧ τε μετέχειν καὐτὸς ὦ τοιχωρύχε.<br>ἧκεν γὰρ ἄν σοι ναστὸς εὖ πεπεμμένος."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἔπειτα τοῦτόν γ᾽ αὐτὸς ἂν κατήσθιες."}, {"st": null, "sp": "Καρίων", "t": "οὐ γὰρ μετεῖχες τὰς ἴσας πληγὰς ἐμοί,<br>ὁπότε τι ληφθείην πανουργήσας ἐγώ."}, {"st": null, "sp": "Ἑρμῆς", "t": "μὴ μνησικακήσῃς, εἰ σὺ Φυλὴν κατέλαβες.<br>ἀλλὰ ξύνοικον πρὸς θεῶν δέξασθέ με."}, {"st": null, "sp": "Καρίων", "t": "ἔπειτ᾽ ἀπολιπὼν τοὺς θεοὺς ἐνθάδε μενεῖς;"}, {"st": null, "sp": "Ἑρμῆς", "t": "τὰ γὰρ παρ᾽ ὑμῖν ἐστι βελτίω πολύ."}, {"st": "1150", "sp": "Καρίων", "t": "τί δέ; ταὐτομολεῖν ἀστεῖον εἶναί σοι δοκεῖ;"}, {"st": null, "sp": "Ἑρμῆς", "t": "πατρὶς γάρ ἐστι πᾶσ᾽ ἵν᾽ ἂν πράττῃ τις εὖ."}, {"st": null, "sp": "Καρίων", "t": "τί δῆτ᾽ ἂν εἴης ὄφελος ἡμῖν ἐνθάδ᾽ ὤν;"}, {"st": null, "sp": "Ἑρμῆς", "t": "παρὰ τὴν θύραν στροφαῖον ἱδρύσασθέ με."}, {"st": null, "sp": "Καρίων", "t": "στροφαῖον; ἀλλ᾽ οὐκ ἔργον ἔστ᾽ οὐδὲν στροφῶν."}, {"st": "1155", "sp": "Ἑρμῆς", "t": "ἀλλ᾽ ἐμπολαῖον."}, {"st": null, "sp": "Καρίων", "t": "ἀλλὰ πλουτοῦμεν: τί οὖν<br>Ἑρμῆν παλιγκάπηλον ἡμᾶς δεῖ τρέφειν;"}, {"st": null, "sp": "Ἑρμῆς", "t": "ἀλλὰ δόλιον τοίνυν."}, {"st": null, "sp": "Καρίων", "t": "δόλιον; ἥκιστά γε:<br>οὐ γὰρ δόλου νῦν ἔργον, ἀλλ᾽ ἁπλῶν τρόπων."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἀλλ᾽ ἡγεμόνιον."}, {"st": null, "sp": "Καρίων", "t": "ἀλλ᾽ ὁ θεὸς ἤδη βλέπει,<br>ὥσθ᾽ ἡγεμόνος οὐδὲν δεησόμεσθ᾽ ἔτι."}, {"st": null, "sp": "Ἑρμῆς", "t": "ἐναγώνιος τοίνυν ἔσομαι. τί δῆτ᾽ ἐρεῖς;<br>Πλούτῳ γάρ ἐστι τοῦτο συμφορώτατον<br>ποιεῖν ἀγῶνας μουσικοὺς καὶ γυμνικούς."}, {"st": null, "sp": "Καρίων", "t": "ὡς ἀγαθόν ἐστ᾽ ἐπωνυμίας πολλὰς ἔχειν:<br>οὗτος γὰρ ἐξηύρηκεν αὑτῷ βιότιον.<br>οὐκ ἐτὸς ἅπαντες οἱ δικάζοντες θαμὰ<br>σπεύδουσιν ἐν πολλοῖς γεγράφθαι γράμμασιν."}, {"st": null, "sp": "Ἑρμῆς", "t": "οὐκοῦν ἐπὶ τούτοις εἰσίω;"}, {"st": null, "sp": "Καρίων", "t": "καὶ πλῦνέ γε<br>αὐτὸς προσελθὼν πρὸς τὸ φρέαρ τὰς κοιλίας,<br>ἵν᾽ εὐθέως διακονικὸς εἶναι δοκῇς."}, {"st": null, "sp": "Ἱερεύς", "t": "τίς ἂν φράσειε ποῦ ‘στι Χρεμύλος μοι σαφῶς;"}, {"st": null, "sp": "Χρεμύλος", "t": "τί δ᾽ ἔστιν ὦ βέλτιστε;"}, {"st": null, "sp": "Ἱερεύς", "t": "τί γὰρ ἀλλ᾽ ἢ κακῶς;<br>ἀφ᾽ οὗ γὰρ ὁ Πλοῦτος οὗτος ἤρξατο βλέπειν,<br>ἀπόλωλ᾽ ὑπὸ λιμοῦ. καταφαγεῖν γὰρ οὐκ ἔχω,<br>καὶ ταῦτα τοῦ σωτῆρος ἱερεὺς ὢν Διός."}, {"st": null, "sp": "Χρεμύλος", "t": "ἡ δ᾽ αἰτία τίς ἐστιν ὦ πρὸς τῶν θεῶν;"}, {"st": null, "sp": "Ἱερεύς", "t": "θύειν ἔτ᾽ οὐδεὶς ἀξιοῖ."}, {"st": null, "sp": "Χρεμύλος", "t": "τίνος οὕνεκα;"}, {"st": null, "sp": "Ἱερεύς", "t": "ὅτι πάντες εἰσὶ πλούσιοι: καίτοι τότε,<br>ὅτ᾽ εἶχον οὐδέν, ὁ μὲν ἂν ἥκων ἔμπορος<br>ἔθυσεν ἱερεῖόν τι σωθείς, ὁ δέ τις ἂν<br>δίκην ἀποφυγών, ὁ δ᾽ ἂν ἐκαλλιερεῖτό τις<br>κἀμέ γ᾽ ἐκάλει τὸν ἱερέα: νῦν δ᾽ οὐδὲ εἷς<br>θύει τὸ παράπαν οὐδὲν οὐδ᾽ εἰσέρχεται,<br>πλὴν ἀποπατησόμενοί γε πλεῖν ἢ μύριοι."}, {"st": "1185", "sp": "Χρεμύλος", "t": "οὔκουν τὰ νομιζόμενα σὺ τούτων λαμβάνεις;"}, {"st": null, "sp": "Ἱερεύς", "t": "τὸν οὖν Δία τὸν σωτῆρα καὐτός μοι δοκῶ<br>χαίρειν ἐάσας ἐνθάδ᾽ αὐτοῦ καταμένειν."}, {"st": null, "sp": "Χρεμύλος", "t": "θάρρει: καλῶς ἔσται γάρ, ἢν θεὸς θέλῃ.<br>ὁ Ζεὺς ὁ σωτὴρ γὰρ πάρεστιν ἐνθάδε,<br>αὐτόματος ἥκων."}, {"st": null, "sp": "Ἱερεύς", "t": "πάντ᾽ ἀγαθὰ τοίνυν λέγεις."}, {"st": null, "sp": "Χρεμύλος", "t": "ἱδρυσόμεθ᾽ οὖν αὐτίκα μάλ᾽, ἀλλὰ περίμενε<br>τὸν Πλοῦτον, οὗπερ πρότερον ἦν ἱδρυμένος<br>τὸν ὀπισθόδομον ἀεὶ φυλάττων τῆς θεοῦ.<br>ἀλλ᾽ ἐκδότω τις δεῦρο δᾷδας ἡμμένας,<br>ἵν᾽ ἔχων προηγῇ τῷ θεῷ σύ."}, {"st": null, "sp": "Ἱερεύς", "t": "πάνυ μὲν οὖν<br>δρᾶν ταῦτα χρή."}, {"st": null, "sp": "Χρεμύλος", "t": "τὸν Πλοῦτον ἔξω τις κάλει."}, {"st": null, "sp": "Γραῦς", "t": "ἐγὼ δὲ τί ποιῶ;"}, {"st": null, "sp": "Χρεμύλος", "t": "τὰς χύτρας, αἷς τὸν θεὸν<br>ἱδρυσόμεθα, λαβοῦσ᾽ ἐπὶ τῆς κεφαλῆς φέρε<br>σεμνῶς: ἔχουσα δ᾽ ἦλθες αὐτὴ ποικίλα."}, {"st": "1200", "sp": "Γραῦς", "t": "ὧν δ᾽ οὕνεκ᾽ ἦλθον;"}, {"st": null, "sp": "Χρεμύλος", "t": "πάντα σοι πεπράξεται.<br>ἥξει γὰρ ὁ νεανίσκος ὡς σ᾽ εἰς ἑσπέραν."}, {"st": null, "sp": "Γραῦς", "t": "ἀλλ᾽ εἴ γε μέντοι νὴ Δί᾽ ἐγγυᾷ σύ μοι<br>ἥξειν ἐκεῖνον ὡς ἔμ᾽, οἴσω τὰς χύτρας."}, {"st": null, "sp": "Χρεμύλος", "t": "καὶ μὴν πολὺ τῶν ἄλλων χυτρῶν τἀναντία<br>αὗται ποιοῦσι: ταῖς μὲν ἄλλαις γὰρ χύτραις<br>ἡ γραῦς ἔπεστ᾽ ἀνωτάτω, ταύτης δὲ νῦν<br>τῆς γραὸς ἐπιπολῆς ἔπεισιν αἱ χύτραι."}, {"st": null, "sp": "Χορός", "t": "οὐκ ἔτι τοίνυν εἰκὸς μέλλειν οὐδ᾽ ἡμᾶς, ἀλλ᾽ ἀναχωρεῖν<br>ἐς τοὔπισθεν: δεῖ γὰρ κατόπιν τούτων ᾁδοντας ἕπεσθαι."}],[]);})();
